content.content:
"""手書きの Markdown の読み取り。

検査 b・k とサブコマンド links-fix が使う要素 (ラベル・リンク・URL・定義の行・アンカー・見出し) を、行と列付きで取り出す。

- ブロックの構造 (コードブロック・HTML のブロック・段落・見出し・表の行の範囲) は、markdown-it-py で CommonMark のとおりに求める。
- 行の中のラベル・インラインコード・エスケープ・インラインの HTML は、このモジュールが自分で読む
  (markdown-it-py は行の範囲を返すが列を返さず、定義の無いラベルをただの文字列として扱うため)。
- コードブロック・mermaid の図・HTML のブロックの中は読まない。行の中では、インラインコード・HTML のコメントとタグ・
  エスケープした「\\[」の中を読まない。
- 画像 (![説明](パス)・![説明][ラベル]) は、リンクとして読まない。reference-style の画像のラベルだけを image_labels に残す
  (その定義の行を、リンクの規則の対象から外すため)。脚注 ([^1])・タスクリストのチェックボックス ([ ]・[x])・
  GitHub の注記 ([!NOTE] など) はラベルとして扱わない。

行と列は 1 から数える。列は文字 (コードポイント) で数える。
書き方の扱いの SSOT は、プラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-docs.md)。
"""

import re
from dataclasses import dataclass, field

from markdown_it import MarkdownIt

# CommonMark で、バックスラッシュでエスケープできる文字 (ASCII の記号)
ASCII_PUNCTUATION = set("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")

# 定義の行。CommonMark の link reference definition のうち、1 行に書いたもの
DEFINITION_RE = re.compile(
    r"^(?P<indent> {0,3})\[(?P<label>(?:[^\[\]\\]|\\.)+)\]:[ \t]*"
    r"(?P<destination><[^<>\n]*>|\S+)"
    r"(?:(?P<space>[ \t]+)(?P<title>\"(?:[^\"\\]|\\.)*\"|'(?:[^'\\]|\\.)*'|\((?:[^()\\]|\\.)*\)))?"
    r"[ \t]*$"
)
# 行の全体に書いたアンカー
ANCHOR_RE = re.compile(r'^\s*<a name="(?P<name>[^"]*)"></a>\s*$')
# 行頭のタスクリストのチェックボックス。引用とリストの記号の後の [ ]・[x]・[X]
TASK_RE = re.compile(r"^[ \t>]*(?:[-+*]|\d{1,9}[.)])[ \t]+(?P<box>\[[ xX]\])(?=[ \t]|$)")
# 引用の先頭の GitHub の注記 ([!NOTE] など)
ALERT_RE = re.compile(r"^[ \t>]*>[ \t]*(?P<alert>\[![A-Za-z]+\])[ \t]*$")
# 山括弧で囲んだ URL (CommonMark の autolink)
AUTOLINK_RE = re.compile(r"<(?P<url>[A-Za-z][A-Za-z0-9+.\-]{1,31}:[^\s<>]*)>")
# メールアドレスの autolink
EMAIL_AUTOLINK_RE = re.compile(r"<(?P<url>[A-Za-z0-9.!#$%&'*+/=?^_`{|}~\-]+@[A-Za-z0-9](?:[A-Za-z0-9\-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9\-]*[A-Za-z0-9])?)*)>")
# インラインの HTML のタグ
HTML_TAG_RE = re.compile(r"</?[A-Za-z][A-Za-z0-9\-]*(?:\s+[^<>]*?)?/?>")
# 文中にそのまま書いた URL。空白・山括弧・ASCII 以外の文字の手前までを URL とする
BARE_URL_RE = re.compile(r"https?://[\x21-\x3b\x3d\x3f-\x7e]+")
# 文中にそのまま書いた URL の末尾から除く文字 (文の句読点として書くことが多いもの)
BARE_URL_TRAILING = ".,:;!?'\")]*_~"


@dataclass(frozen=True)
class Reference:
    """reference-style のリンクの、本文での使用。"""

    form: str  # "shortcut" ([ラベル])・"full" ([文][ラベル])・"collapsed" ([ラベル][])
    text: str  # 最初の角括弧の中
    label: str  # 定義の行と比べるラベル。shortcut と collapsed では text と同じ
    line: int
    column: int  # 最初の「[」の列
    label_line: int  # ラベルの「[」の行 (shortcut と collapsed では line と同じ)
    label_column: int
    end_line: int  # リンクの最後の「]」がある行
    end_column: int  # リンクの最後の「]」がある列


@dataclass(frozen=True)
class InlineLink:
    """[文](URL) の形のリンク。"""

    text: str
    destination: str
    line: int
    column: int


@dataclass(frozen=True)
class Url:
    """<URL> の形のリンク (form が "autolink") と、文中にそのまま書いた URL (form が "bare")。"""

    form: str
    url: str
    line: int
    column: int


@dataclass(frozen=True)
class Definition:
    """定義の行。"""

    label: str  # 角括弧の中 (エスケープはそのまま)
    destination: str  # 書いたとおり (山括弧で囲んだものは囲みを含む)
    title: str | None  # 引用符の中 (エスケープはそのまま)。title が無ければ None
    quote: str | None  # title の開きの引用符 (「"」「'」「(」)
    line: int
    column: int  # 「[」の列
    in_paragraph: bool  # 直前の段落の一部になり、CommonMark では定義の行として読まれない
    title_start: int  # 行の中の、title の開きの引用符の位置 (0 から数える)。title が無ければ行の長さ

    @property
    def title_text(self) -> str | None:
        """title のエスケープを解いた文。"""
        return None if self.title is None else unescape(self.title)


@dataclass(frozen=True)
class Anchor:
    name: str
    line: int
    column: int


@dataclass(frozen=True)
class Heading:
    level: int
    text: str  # 行頭の「#」と前後の空白、末尾の閉じの「#」を除いた文
    line: int
    atx: bool  # 「#」で書いた見出しなら True、下線 (=== や ---) で書いた見出しなら False


@dataclass
class Document:
    lines: list[str]  # 改行を除いた行
    references: list[Reference] = field(default_factory=list)
    inline_links: list[InlineLink] = field(default_factory=list)
    urls: list[Url] = field(default_factory=list)
    definitions: list[Definition] = field(default_factory=list)
    anchors: list[Anchor] = field(default_factory=list)
    headings: list[Heading] = field(default_factory=list)
    # reference-style の画像 (![説明][ラベル]・![ラベル][]・![ラベル]) が使うラベル
    image_labels: list[str] = field(default_factory=list)
    # 本文の行数。末尾の定義の行のまとまり (定義の行と、その間と前後の空行) を除いた、先頭からの行数
    body_end: int = 0

    def definition_lines(self) -> set[int]:
        return {d.line for d in self.definitions}

    def next_nonblank(self, line: int) -> int | None:
        """line (1 から数える) の後の、空行でない最初の行。無ければ None。"""
        for index in range(line, len(self.lines)):
            if self.lines[index].strip():
                return index + 1
        return None

    def first_nonblank(self) -> int | None:
        return self.next_nonblank(0)

    def heading_at(self, line: int) -> Heading | None:
        for heading in self.headings:
            if heading.line == line:
                return heading
        return None


def normalize_label(label: str) -> str:
    """CommonMark のとおりにラベルを比べる形にする (英字の大文字と小文字の違いと、連続する空白の違いを無視する)。"""
    return " ".join(label.split()).casefold()


def unescape(text: str) -> str:
    """バックスラッシュのエスケープを解く。"""
    result = []
    i = 0
    while i < len(text):
        if text[i] == "\\" and i + 1 < len(text) and text[i + 1] in ASCII_PUNCTUATION:
            result.append(text[i + 1])
            i += 2
            continue
        result.append(text[i])
        i += 1
    return "".join(result)


def escape_title(text: str, quote: str) -> str:
    """title に書く文を、引用符の種類に合わせてエスケープする。"""
    text = text.replace("\\", "\\\\")
    if quote == '"':
        return text.replace('"', '\\"')
    if quote == "'":
        return text.replace("'", "\\'")
    return text.replace("(", "\\(").replace(")", "\\)")


def closing_quote(quote: str) -> str:
    return ")" if quote == "(" else quote


def heading_text(line: str) -> str:
    """「#」で書いた見出しの行から、見出しの文を取り出す。"""
    text = line.strip()
    text = text.lstrip("#")
    text = text.strip()
    # 末尾の閉じの「#」は、前に空白があるときだけ除く (CommonMark のとおり)
    match = re.search(r"(?:^|[ \t])#+$", text)
    if match:
        text = text[: match.start()]
    return text.strip()


_PARSER = MarkdownIt("commonmark").enable("table")


def parse(text: str) -> Document:
    lines = text.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    document = Document(lines=lines)
    tokens = _PARSER.parse("\n".join(lines) + "\n")

    code_lines: set[int] = set()  # 0 から数える。コードブロック・HTML のブロックの行
    inline_ranges: list[tuple[int, int]] = []
    paragraph_lines: set[int] = set()
    for token in tokens:
        if token.map is None:
            continue
        start, end = token.map
        if token.type in ("fence", "code_block", "html_block"):
            code_lines.update(range(start, end))
        elif token.type == "inline":
            if (start, end) not in inline_ranges:
                inline_ranges.append((start, end))
        elif token.type == "paragraph_open":
            paragraph_lines.update(range(start, end))
        elif token.type == "heading_open":
            if token.markup.startswith("#"):
                document.headings.append(
                    Heading(len(token.markup), heading_text(lines[start]), start + 1, True)
                )
            else:
                level = 1 if token.markup == "=" else 2
                document.headings.append(Heading(level, lines[start].strip(), start + 1, False))

    definition_indexes: set[int] = set()
    for index, line in enumerate(lines):
        if index in code_lines:
            continue
        match = DEFINITION_RE.match(line)
        if match and not match.group("label").startswith("^"):
            title = match.group("title")
            document.definitions.append(
                Definition(
                    label=match.group("label"),
                    destination=match.group("destination"),
                    title=title[1:-1] if title else None,
                    quote=title[0] if title else None,
                    line=index + 1,
                    column=len(match.group("indent")) + 1,
                    in_paragraph=index in paragraph_lines,
                    title_start=match.start("title") if title else len(line),
                )
            )
            definition_indexes.add(index)
            continue
        anchor = ANCHOR_RE.match(line)
        if anchor:
            document.anchors.append(Anchor(anchor.group("name"), index + 1, line.index("<") + 1))

    for start, end in inline_ranges:
        _InlineScanner(document, lines, start, end, definition_indexes).scan()

    document.references.sort(key=lambda r: (r.line, r.column))
    document.inline_links.sort(key=lambda r: (r.line, r.column))
    document.urls.sort(key=lambda r: (r.line, r.column))
    document.body_end = _body_end(lines, definition_indexes)
    return document


def _body_end(lines: list[str], definition_indexes: set[int]) -> int:
    index = len(lines)
    found = False
    while index > 0:
        previous = index - 1
        if previous in definition_indexes:
            found = True
        elif lines[previous].strip():
            break
        index -= 1
    return index if found else len(lines)


class _InlineScanner:
    """段落・見出し・表の 1 つのブロックの中の、行の中の要素を読む。"""

    def __init__(self, document: Document, lines: list[str], start: int, end: int, skip: set[int]):
        self.document = document
        # 定義の行 (段落の一部になったもの) は、行の中の要素として読まない
        kept = [i for i in range(start, end) if i not in skip]
        self.text = ""
        self.positions: list[tuple[int, int]] = []  # text の各文字の (行, 列)。どちらも 1 から数える
        self.line_starts: dict[int, int] = {}  # text の中の、各行の先頭の位置
        for i in kept:
            self.line_starts[i] = len(self.text)
            for column, _ in enumerate(lines[i]):
                self.positions.append((i + 1, column + 1))
            self.text += lines[i]
            self.positions.append((i + 1, len(lines[i]) + 1))
            self.text += "\n"
        self.ignored: set[int] = set()  # ラベルとして扱わない「[」の位置
        for i in kept:
            for regex, group in ((TASK_RE, "box"), (ALERT_RE, "alert")):
                match = regex.match(lines[i])
                if match:
                    self.ignored.add(self.line_starts[i] + match.start(group))

    def position(self, offset: int) -> tuple[int, int]:
        return self.positions[offset]

    def scan(self) -> None:
        text = self.text
        i = 0
        while i < len(text):
            char = text[i]
            if char == "\\" and i + 1 < len(text) and text[i + 1] in ASCII_PUNCTUATION:
                i += 2
            elif char == "`":
                i = self.skip_code(i)
            elif char == "<":
                i = self.read_angle(i)
            elif char == "!" and text.startswith("[", i + 1):
                i = self.skip_image(i + 1)
            elif char == "[":
                i = self.read_bracket(i)
            elif text.startswith(("http://", "https://"), i) and (i == 0 or not text[i - 1].isalnum()):
                i = self.read_bare_url(i)
            else:
                i += 1

    def skip_code(self, i: int) -> int:
        """インラインコードを読み飛ばす。閉じが無ければ、バッククォートの並びだけを読み飛ばす。"""
        text = self.text
        run_end = i
        while run_end < len(text) and text[run_end] == "`":
            run_end += 1
        run = run_end - i
        j = run_end
        while j < len(text):
            if text[j] == "`":
                k = j
                while k < len(text) and text[k] == "`":
                    k += 1
                if k - j == run:
                    return k
                j = k
            else:
                j += 1
        return run_end

    def angle_end(self, i: int) -> tuple[int, str | None]:
        """text[i] の「<」で始まる要素 (HTML のコメント・autolink・HTML のタグ) の終わりの位置と、autolink なら その URL。
        どれでもなければ、「<」の次の位置。"""
        text = self.text
        if text.startswith("<!--", i):
            end = text.find("-->", i + 4)
            return (len(text) if end < 0 else end + 3), None
        for regex in (AUTOLINK_RE, EMAIL_AUTOLINK_RE):
            match = regex.match(text, i)
            if match:
                return match.end(), match.group("url")
        match = HTML_TAG_RE.match(text, i)
        if match:
            return match.end(), None
        return i + 1, None

    def read_angle(self, i: int) -> int:
        end, url = self.angle_end(i)
        if url is not None:
            line, column = self.position(i)
            self.document.urls.append(Url("autolink", url, line, column))
        return end

    def read_bare_url(self, i: int) -> int:
        match = BARE_URL_RE.match(self.text, i)
        url = match.group(0).rstrip(BARE_URL_TRAILING)
        if url.endswith("://") or len(url) <= len("https://"):
            return i + len(url) if url else i + 1
        line, column = self.position(i)
        self.document.urls.append(Url("bare", url, line, column))
        return i + len(url)

    def matching_bracket(self, i: int) -> int | None:
        """text[i] の「[」に対応する「]」の位置。インラインコードとエスケープの中の角括弧は数えない。"""
        text = self.text
        depth = 0
        j = i
        while j < len(text):
            char = text[j]
            if char == "\\" and j + 1 < len(text) and text[j + 1] in ASCII_PUNCTUATION:
                j += 2
                continue
            if char == "`":
                j = self.skip_code(j)
                continue
            if char == "[":
                depth += 1
            elif char == "]":
                depth -= 1
                if depth == 0:
                    return j
            j += 1
        return None

    def matching_paren(self, i: int) -> int | None:
        text = self.text
        depth = 0
        j = i
        while j < len(text):
            char = text[j]
            if char == "\\" and j + 1 < len(text) and text[j + 1] in ASCII_PUNCTUATION:
                j += 2
                continue
            if char == "(":
                depth += 1
            elif char == ")":
                depth -= 1
                if depth == 0:
                    return j
            j += 1
        return None

    def skip_image(self, i: int) -> int:
        close = self.matching_bracket(i)
        if close is None:
            return i + 1
        after = close + 1
        if self.text.startswith("(", after):
            paren = self.matching_paren(after)
            if paren is not None:
                return paren + 1
        inner = self.text[i + 1 : close]
        if self.text.startswith("[", after):
            label_close = self.matching_bracket(after)
            if label_close is not None:
                label = self.text[after + 1 : label_close]
                self.document.image_labels.append(label if label.strip() else inner)
                return label_close + 1
        if inner.strip():
            self.document.image_labels.append(inner)
        return after

    def scan_images(self, start: int, end: int) -> None:
        """text[start:end] (リンクの文) の中の画像を読む。エスケープ・インラインコード・HTML・autolink の中は読まない。"""
        text = self.text
        j = start
        while j < end:
            char = text[j]
            if char == "\\" and j + 1 < len(text) and text[j + 1] in ASCII_PUNCTUATION:
                j += 2
            elif char == "`":
                j = self.skip_code(j)
            elif char == "<":
                j = self.angle_end(j)[0]
            elif char == "!" and text.startswith("[", j + 1):
                j = self.skip_image(j + 1)
            else:
                j += 1

    def read_bracket(self, i: int) -> int:
        text = self.text
        if i in self.ignored or text.startswith("[^", i):
            close = self.matching_bracket(i)
            return i + 1 if close is None else close + 1
        close = self.matching_bracket(i)
        if close is None:
            return i + 1
        inner = text[i + 1 : close]
        if not inner.strip():
            # [] はリンクにならない (CommonMark のとおり)
            return close + 1
        line, column = self.position(i)
        # リンクの文の中の画像 ([![CI][ci-badge]][ci] のようなバッジ) のラベルも残す
        self.scan_images(i + 1, close)
        after = close + 1
        if text.startswith("(", after):
            paren = self.matching_paren(after)
            if paren is not None:
                destination = text[after + 1 : paren].strip().split(maxsplit=1)
                self.document.inline_links.append(
                    InlineLink(inner, destination[0] if destination else "", line, column)
                )
                return paren + 1
        if text.startswith("[", after):
            label_close = self.matching_bracket(after)
            if label_close is not None:
                label = text[after + 1 : label_close]
                label_line, label_column = self.position(after)
                end = self.position(label_close)
                if label.strip():
                    self.document.references.append(
                        Reference("full", inner, label, line, column, label_line, label_column, *end)
                    )
                else:
                    self.document.references.append(
                        Reference("collapsed", inner, inner, line, column, line, column, *end)
                    )
                return label_close + 1
        self.document.references.append(
            Reference("shortcut", inner, inner, line, column, line, column, *self.position(close))
        )
        return after

toolUseResult.stdout:
"""手書きの Markdown の読み取り。

検査 b・k とサブコマンド links-fix が使う要素 (ラベル・リンク・URL・定義の行・アンカー・見出し) を、行と列付きで取り出す。

- ブロックの構造 (コードブロック・HTML のブロック・段落・見出し・表の行の範囲) は、markdown-it-py で CommonMark のとおりに求める。
- 行の中のラベル・インラインコード・エスケープ・インラインの HTML は、このモジュールが自分で読む
  (markdown-it-py は行の範囲を返すが列を返さず、定義の無いラベルをただの文字列として扱うため)。
- コードブロック・mermaid の図・HTML のブロックの中は読まない。行の中では、インラインコード・HTML のコメントとタグ・
  エスケープした「\\[」の中を読まない。
- 画像 (![説明](パス)・![説明][ラベル]) は、リンクとして読まない。reference-style の画像のラベルだけを image_labels に残す
  (その定義の行を、リンクの規則の対象から外すため)。脚注 ([^1])・タスクリストのチェックボックス ([ ]・[x])・
  GitHub の注記 ([!NOTE] など) はラベルとして扱わない。

行と列は 1 から数える。列は文字 (コードポイント) で数える。
書き方の扱いの SSOT は、プラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-docs.md)。
"""

import re
from dataclasses import dataclass, field

from markdown_it import MarkdownIt

# CommonMark で、バックスラッシュでエスケープできる文字 (ASCII の記号)
ASCII_PUNCTUATION = set("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")

# 定義の行。CommonMark の link reference definition のうち、1 行に書いたもの
DEFINITION_RE = re.compile(
    r"^(?P<indent> {0,3})\[(?P<label>(?:[^\[\]\\]|\\.)+)\]:[ \t]*"
    r"(?P<destination><[^<>\n]*>|\S+)"
    r"(?:(?P<space>[ \t]+)(?P<title>\"(?:[^\"\\]|\\.)*\"|'(?:[^'\\]|\\.)*'|\((?:[^()\\]|\\.)*\)))?"
    r"[ \t]*$"
)
# 行の全体に書いたアンカー
ANCHOR_RE = re.compile(r'^\s*<a name="(?P<name>[^"]*)"></a>\s*$')
# 行頭のタスクリストのチェックボックス。引用とリストの記号の後の [ ]・[x]・[X]
TASK_RE = re.compile(r"^[ \t>]*(?:[-+*]|\d{1,9}[.)])[ \t]+(?P<box>\[[ xX]\])(?=[ \t]|$)")
# 引用の先頭の GitHub の注記 ([!NOTE] など)
ALERT_RE = re.compile(r"^[ \t>]*>[ \t]*(?P<alert>\[![A-Za-z]+\])[ \t]*$")
# 山括弧で囲んだ URL (CommonMark の autolink)
AUTOLINK_RE = re.compile(r"<(?P<url>[A-Za-z][A-Za-z0-9+.\-]{1,31}:[^\s<>]*)>")
# メールアドレスの autolink
EMAIL_AUTOLINK_RE = re.compile(r"<(?P<url>[A-Za-z0-9.!#$%&'*+/=?^_`{|}~\-]+@[A-Za-z0-9](?:[A-Za-z0-9\-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9\-]*[A-Za-z0-9])?)*)>")
# インラインの HTML のタグ
HTML_TAG_RE = re.compile(r"</?[A-Za-z][A-Za-z0-9\-]*(?:\s+[^<>]*?)?/?>")
# 文中にそのまま書いた URL。空白・山括弧・ASCII 以外の文字の手前までを URL とする
BARE_URL_RE = re.compile(r"https?://[\x21-\x3b\x3d\x3f-\x7e]+")
# 文中にそのまま書いた URL の末尾から除く文字 (文の句読点として書くことが多いもの)
BARE_URL_TRAILING = ".,:;!?'\")]*_~"


@dataclass(frozen=True)
class Reference:
    """reference-style のリンクの、本文での使用。"""

    form: str  # "shortcut" ([ラベル])・"full" ([文][ラベル])・"collapsed" ([ラベル][])
    text: str  # 最初の角括弧の中
    label: str  # 定義の行と比べるラベル。shortcut と collapsed では text と同じ
    line: int
    column: int  # 最初の「[」の列
    label_line: int  # ラベルの「[」の行 (shortcut と collapsed では line と同じ)
    label_column: int
    end_line: int  # リンクの最後の「]」がある行
    end_column: int  # リンクの最後の「]」がある列


@dataclass(frozen=True)
class InlineLink:
    """[文](URL) の形のリンク。"""

    text: str
    destination: str
    line: int
    column: int


@dataclass(frozen=True)
class Url:
    """<URL> の形のリンク (form が "autolink") と、文中にそのまま書いた URL (form が "bare")。"""

    form: str
    url: str
    line: int
    column: int


@dataclass(frozen=True)
class Definition:
    """定義の行。"""

    label: str  # 角括弧の中 (エスケープはそのまま)
    destination: str  # 書いたとおり (山括弧で囲んだものは囲みを含む)
    title: str | None  # 引用符の中 (エスケープはそのまま)。title が無ければ None
    quote: str | None  # title の開きの引用符 (「"」「'」「(」)
    line: int
    column: int  # 「[」の列
    in_paragraph: bool  # 直前の段落の一部になり、CommonMark では定義の行として読まれない
    title_start: int  # 行の中の、title の開きの引用符の位置 (0 から数える)。title が無ければ行の長さ

    @property
    def title_text(self) -> str | None:
        """title のエスケープを解いた文。"""
        return None if self.title is None else unescape(self.title)


@dataclass(frozen=True)
class Anchor:
    name: str
    line: int
    column: int


@dataclass(frozen=True)
class Heading:
    level: int
    text: str  # 行頭の「#」と前後の空白、末尾の閉じの「#」を除いた文
    line: int
    atx: bool  # 「#」で書いた見出しなら True、下線 (=== や ---) で書いた見出しなら False


@dataclass
class Document:
    lines: list[str]  # 改行を除いた行
    references: list[Reference] = field(default_factory=list)
    inline_links: list[InlineLink] = field(default_factory=list)
    urls: list[Url] = field(default_factory=list)
    definitions: list[Definition] = field(default_factory=list)
    anchors: list[Anchor] = field(default_factory=list)
    headings: list[Heading] = field(default_factory=list)
    # reference-style の画像 (![説明][ラベル]・![ラベル][]・![ラベル]) が使うラベル
    image_labels: list[str] = field(default_factory=list)
    # 本文の行数。末尾の定義の行のまとまり (定義の行と、その間と前後の空行) を除いた、先頭からの行数
    body_end: int = 0

    def definition_lines(self) -> set[int]:
        return {d.line for d in self.definitions}

    def next_nonblank(self, line: int) -> int | None:
        """line (1 から数える) の後の、空行でない最初の行。無ければ None。"""
        for index in range(line, len(self.lines)):
            if self.lines[index].strip():
                return index + 1
        return None

    def first_nonblank(self) -> int | None:
        return self.next_nonblank(0)

    def heading_at(self, line: int) -> Heading | None:
        for heading in self.headings:
            if heading.line == line:
                return heading
        return None


def normalize_label(label: str) -> str:
    """CommonMark のとおりにラベルを比べる形にする (英字の大文字と小文字の違いと、連続する空白の違いを無視する)。"""
    return " ".join(label.split()).casefold()


def unescape(text: str) -> str:
    """バックスラッシュのエスケープを解く。"""
    result = []
    i = 0
    while i < len(text):
        if text[i] == "\\" and i + 1 < len(text) and text[i + 1] in ASCII_PUNCTUATION:
            result.append(text[i + 1])
            i += 2
            continue
        result.append(text[i])
        i += 1
    return "".join(result)


def escape_title(text: str, quote: str) -> str:
    """title に書く文を、引用符の種類に合わせてエスケープする。"""
    text = text.replace("\\", "\\\\")
    if quote == '"':
        return text.replace('"', '\\"')
    if quote == "'":
        return text.replace("'", "\\'")
    return text.replace("(", "\\(").replace(")", "\\)")


def closing_quote(quote: str) -> str:
    return ")" if quote == "(" else quote


def heading_text(line: str) -> str:
    """「#」で書いた見出しの行から、見出しの文を取り出す。"""
    text = line.strip()
    text = text.lstrip("#")
    text = text.strip()
    # 末尾の閉じの「#」は、前に空白があるときだけ除く (CommonMark のとおり)
    match = re.search(r"(?:^|[ \t])#+$", text)
    if match:
        text = text[: match.start()]
    return text.strip()


_PARSER = MarkdownIt("commonmark").enable("table")


def parse(text: str) -> Document:
    lines = text.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    document = Document(lines=lines)
    tokens = _PARSER.parse("\n".join(lines) + "\n")

    code_lines: set[int] = set()  # 0 から数える。コードブロック・HTML のブロックの行
    inline_ranges: list[tuple[int, int]] = []
    paragraph_lines: set[int] = set()
    for token in tokens:
        if token.map is None:
            continue
        start, end = token.map
        if token.type in ("fence", "code_block", "html_block"):
            code_lines.update(range(start, end))
        elif token.type == "inline":
            if (start, end) not in inline_ranges:
                inline_ranges.append((start, end))
        elif token.type == "paragraph_open":
            paragraph_lines.update(range(start, end))
        elif token.type == "heading_open":
            if token.markup.startswith("#"):
                document.headings.append(
                    Heading(len(token.markup), heading_text(lines[start]), start + 1, True)
                )
            else:
                level = 1 if token.markup == "=" else 2
                document.headings.append(Heading(level, lines[start].strip(), start + 1, False))

    definition_indexes: set[int] = set()
    for index, line in enumerate(lines):
        if index in code_lines:
            continue
        match = DEFINITION_RE.match(line)
        if match and not match.group("label").startswith("^"):
            title = match.group("title")
            document.definitions.append(
                Definition(
                    label=match.group("label"),
                    destination=match.group("destination"),
                    title=title[1:-1] if title else None,
                    quote=title[0] if title else None,
                    line=index + 1,
                    column=len(match.group("indent")) + 1,
                    in_paragraph=index in paragraph_lines,
                    title_start=match.start("title") if title else len(line),
                )
            )
            definition_indexes.add(index)
            continue
        anchor = ANCHOR_RE.match(line)
        if anchor:
            document.anchors.append(Anchor(anchor.group("name"), index + 1, line.index("<") + 1))

    for start, end in inline_ranges:
        _InlineScanner(document, lines, start, end, definition_indexes).scan()

    document.references.sort(key=lambda r: (r.line, r.column))
    document.inline_links.sort(key=lambda r: (r.line, r.column))
    document.urls.sort(key=lambda r: (r.line, r.column))
    document.body_end = _body_end(lines, definition_indexes)
    return document


def _body_end(lines: list[str], definition_indexes: set[int]) -> int:
    index = len(lines)
    found = False
    while index > 0:
        previous = index - 1
        if previous in definition_indexes:
            found = True
        elif lines[previous].strip():
            break
        index -= 1
    return index if found else len(lines)


class _InlineScanner:
    """段落・見出し・表の 1 つのブロックの中の、行の中の要素を読む。"""

    def __init__(self, document: Document, lines: list[str], start: int, end: int, skip: set[int]):
        self.document = document
        # 定義の行 (段落の一部になったもの) は、行の中の要素として読まない
        kept = [i for i in range(start, end) if i not in skip]
        self.text = ""
        self.positions: list[tuple[int, int]] = []  # text の各文字の (行, 列)。どちらも 1 から数える
        self.line_starts: dict[int, int] = {}  # text の中の、各行の先頭の位置
        for i in kept:
            self.line_starts[i] = len(self.text)
            for column, _ in enumerate(lines[i]):
                self.positions.append((i + 1, column + 1))
            self.text += lines[i]
            self.positions.append((i + 1, len(lines[i]) + 1))
            self.text += "\n"
        self.ignored: set[int] = set()  # ラベルとして扱わない「[」の位置
        for i in kept:
            for regex, group in ((TASK_RE, "box"), (ALERT_RE, "alert")):
                match = regex.match(lines[i])
                if match:
                    self.ignored.add(self.line_starts[i] + match.start(group))

    def position(self, offset: int) -> tuple[int, int]:
        return self.positions[offset]

    def scan(self) -> None:
        text = self.text
        i = 0
        while i < len(text):
            char = text[i]
            if char == "\\" and i + 1 < len(text) and text[i + 1] in ASCII_PUNCTUATION:
                i += 2
            elif char == "`":
                i = self.skip_code(i)
            elif char == "<":
                i = self.read_angle(i)
            elif char == "!" and text.startswith("[", i + 1):
                i = self.skip_image(i + 1)
            elif char == "[":
                i = self.read_bracket(i)
            elif text.startswith(("http://", "https://"), i) and (i == 0 or not text[i - 1].isalnum()):
                i = self.read_bare_url(i)
            else:
                i += 1

    def skip_code(self, i: int) -> int:
        """インラインコードを読み飛ばす。閉じが無ければ、バッククォートの並びだけを読み飛ばす。"""
        text = self.text
        run_end = i
        while run_end < len(text) and text[run_end] == "`":
            run_end += 1
        run = run_end - i
        j = run_end
        while j < len(text):
            if text[j] == "`":
                k = j
                while k < len(text) and text[k] == "`":
                    k += 1
                if k - j == run:
                    return k
                j = k
            else:
                j += 1
        return run_end

    def angle_end(self, i: int) -> tuple[int, str | None]:
        """text[i] の「<」で始まる要素 (HTML のコメント・autolink・HTML のタグ) の終わりの位置と、autolink なら その URL。
        どれでもなければ、「<」の次の位置。"""
        text = self.text
        if text.startswith("<!--", i):
            end = text.find("-->", i + 4)
            return (len(text) if end < 0 else end + 3), None
        for regex in (AUTOLINK_RE, EMAIL_AUTOLINK_RE):
            match = regex.match(text, i)
            if match:
                return match.end(), match.group("url")
        match = HTML_TAG_RE.match(text, i)
        if match:
            return match.end(), None
        return i + 1, None

    def read_angle(self, i: int) -> int:
        end, url = self.angle_end(i)
        if url is not None:
            line, column = self.position(i)
            self.document.urls.append(Url("autolink", url, line, column))
        return end

    def read_bare_url(self, i: int) -> int:
        match = BARE_URL_RE.match(self.text, i)
        url = match.group(0).rstrip(BARE_URL_TRAILING)
        if url.endswith("://") or len(url) <= len("https://"):
            return i + len(url) if url else i + 1
        line, column = self.position(i)
        self.document.urls.append(Url("bare", url, line, column))
        return i + len(url)

    def matching_bracket(self, i: int) -> int | None:
        """text[i] の「[」に対応する「]」の位置。インラインコードとエスケープの中の角括弧は数えない。"""
        text = self.text
        depth = 0
        j = i
        while j < len(text):
            char = text[j]
            if char == "\\" and j + 1 < len(text) and text[j + 1] in ASCII_PUNCTUATION:
                j += 2
                continue
            if char == "`":
                j = self.skip_code(j)
                continue
            if char == "[":
                depth += 1
            elif char == "]":
                depth -= 1
                if depth == 0:
                    return j
            j += 1
        return None

    def matching_paren(self, i: int) -> int | None:
        text = self.text
        depth = 0
        j = i
        while j < len(text):
            char = text[j]
            if char == "\\" and j + 1 < len(text) and text[j + 1] in ASCII_PUNCTUATION:
                j += 2
                continue
            if char == "(":
                depth += 1
            elif char == ")":
                depth -= 1
                if depth == 0:
                    return j
            j += 1
        return None

    def skip_image(self, i: int) -> int:
        close = self.matching_bracket(i)
        if close is None:
            return i + 1
        after = close + 1
        if self.text.startswith("(", after):
            paren = self.matching_paren(after)
            if paren is not None:
                return paren + 1
        inner = self.text[i + 1 : close]
        if self.text.startswith("[", after):
            label_close = self.matching_bracket(after)
            if label_close is not None:
                label = self.text[after + 1 : label_close]
                self.document.image_labels.append(label if label.strip() else inner)
                return label_close + 1
        if inner.strip():
            self.document.image_labels.append(inner)
        return after

    def scan_images(self, start: int, end: int) -> None:
        """text[start:end] (リンクの文) の中の画像を読む。エスケープ・インラインコード・HTML・autolink の中は読まない。"""
        text = self.text
        j = start
        while j < end:
            char = text[j]
            if char == "\\" and j + 1 < len(text) and text[j + 1] in ASCII_PUNCTUATION:
                j += 2
            elif char == "`":
                j = self.skip_code(j)
            elif char == "<":
                j = self.angle_end(j)[0]
            elif char == "!" and text.startswith("[", j + 1):
                j = self.skip_image(j + 1)
            else:
                j += 1

    def read_bracket(self, i: int) -> int:
        text = self.text
        if i in self.ignored or text.startswith("[^", i):
            close = self.matching_bracket(i)
            return i + 1 if close is None else close + 1
        close = self.matching_bracket(i)
        if close is None:
            return i + 1
        inner = text[i + 1 : close]
        if not inner.strip():
            # [] はリンクにならない (CommonMark のとおり)
            return close + 1
        line, column = self.position(i)
        # リンクの文の中の画像 ([![CI][ci-badge]][ci] のようなバッジ) のラベルも残す
        self.scan_images(i + 1, close)
        after = close + 1
        if text.startswith("(", after):
            paren = self.matching_paren(after)
            if paren is not None:
                destination = text[after + 1 : paren].strip().split(maxsplit=1)
                self.document.inline_links.append(
                    InlineLink(inner, destination[0] if destination else "", line, column)
                )
                return paren + 1
        if text.startswith("[", after):
            label_close = self.matching_bracket(after)
            if label_close is not None:
                label = text[after + 1 : label_close]
                label_line, label_column = self.position(after)
                end = self.position(label_close)
                if label.strip():
                    self.document.references.append(
                        Reference("full", inner, label, line, column, label_line, label_column, *end)
                    )
                else:
                    self.document.references.append(
                        Reference("collapsed", inner, inner, line, column, line, column, *end)
                    )
                return label_close + 1
        self.document.references.append(
            Reference("shortcut", inner, inner, line, column, line, column, *self.position(close))
        )
        return after

content.content:
"""手書きの Markdown と、リンクの参照先の一覧。

ドメインのディレクトリの下の手書きの Markdown を見つけ、すべての Markdown (生成したファイルを含む) のアンカーから、
リンクの参照先の一覧を作る。形式の SSOT はプラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-docs.md と
doc-structured/rules/doc-structured-domains.md)。要点:
  - 手書きのファイルは、ドメインのディレクトリの直下の concept.md・problem.md・design.md と、
    その種類と同じ名前のサブディレクトリの <名前>.md (子のファイル。1 階層だけ)
  - ほかの名前・場所の .md は、検査 b のエラーにする
  - 参照先のアンカーは、今のファイルの内容から読む (生成したファイルが古いことは検査 a が報告する)。YAML から決まる参照先
    (ドメイン・定義・生成したファイル) のファイルは、生成する側の対応で決め、そのファイルにアンカーがあるときだけ参照先にする
  - 参照先のラベルの候補は、ID・名前・書ける形 (「種類 + 名前」に、親を直近から 0 個以上足した形。略称のある種類は、
    略称で書いた形も含む)
"""

import posixpath
from dataclasses import dataclass, field
from pathlib import Path

from . import generated_header, markdown, names
from .domains import DOMAINS_DIR, Domain, Project, rel
from .generate import entry_file, file_path
from .names import Part
from .problems import Problem

README = "README.md"
# ドメインのディレクトリの直下の、生成するファイルの名前
GENERATED_NAMES = {README, *names.FILE_KINDS.values()}


@dataclass
class HandwrittenFile:
    """ドメインのディレクトリの下の、手書きのファイル。"""

    path: str  # リポジトリのルートからの相対パス
    domain: Domain
    symbol: str  # 手書きのファイルの種類の記号 (concept・problem・design)
    child: str | None  # 子のファイルなら、その名前
    document: markdown.Document

    @property
    def id(self) -> str:
        parts = [Part("d", self.domain.name), Part(self.symbol, None)]
        if self.child is not None:
            parts.append(Part(names.CHILD_FILE_SYMBOL, self.child))
        return names.build_id(parts)

    @property
    def display(self) -> str:
        """限定付きの名前に書くファイル名。子のファイルは、ドメインのディレクトリからのパス。"""
        if self.child is None:
            return names.HANDWRITTEN_FILE_KINDS[self.symbol]
        return f"{self.symbol}/{self.child}.md"

    def parts(self) -> list[str]:
        symbol = names.CHILD_FILE_SYMBOL if self.child is not None else self.symbol
        return [self.domain.full_name(), names.format_part(symbol, self.display)]

    def full_name(self) -> str:
        return names.join_parts(self.parts())


@dataclass
class Target:
    """リンクの参照先 (アンカーのある定義・ファイル・節)。"""

    id: str
    path: str  # アンカーを書いたファイルの、リポジトリのルートからの相対パス
    parts: list[str]  # ドメインから自分までの「種類 + 名前」
    name: str | None  # ラベルの候補にする名前 (日本語名・見出しの文・コードの書式のファイル名)。ドメインは名前を持たない
    abbreviated: str | None = None  # 自分の「種類 + 名前」を略称で書いたもの。種類に略称が無ければ None

    def full_name(self) -> str:
        return names.join_parts(self.parts)

    def writable_forms(self) -> list[str]:
        """本文で最初に指す箇所に書ける形。完全な名前の先頭から親を 0 個以上省いた形で、短い順に並べる。
        略称のある種類は、同じ親の数の形を、略称で書いた形・正式名称で書いた形の順に並べる。"""
        forms: list[str] = []
        for i in range(len(self.parts) - 1, -1, -1):
            if self.abbreviated is not None:
                forms.append(names.join_parts(self.parts[i:-1] + [self.abbreviated]))
            forms.append(names.join_parts(self.parts[i:]))
        return forms

    def form_for(self, from_parts: list[str]) -> str:
        """from_parts (参照するファイルの「種類 + 名前」の並び) のファイルから最初に指す箇所に、サブコマンド links-fix が
        書く形。参照するファイルと共通の親を省き、自分の「種類 + 名前」は略称があれば略称で書く。"""
        common = 0
        while common < len(self.parts) - 1 and common < len(from_parts) and self.parts[common] == from_parts[common]:
            common += 1
        own = self.abbreviated if self.abbreviated is not None else self.parts[-1]
        return names.join_parts(self.parts[common:-1] + [own])

    def labels(self) -> set[str]:
        """ラベルの候補を、比べる形 (markdown.normalize_label) にしたもの。"""
        found = {self.id, *self.writable_forms()}
        if self.name:
            found.add(self.name)
        return {markdown.normalize_label(label) for label in found}

    def href(self, from_path: str) -> str:
        """from_path のファイルに書く、定義の行の href。"""
        if self.path == from_path:
            return f"#{self.id}"
        return f"{posixpath.relpath(self.path, posixpath.dirname(from_path))}#{self.id}"


@dataclass
class Index:
    files: list[HandwrittenFile] = field(default_factory=list)
    targets: dict[str, Target] = field(default_factory=dict)
    # すべての Markdown のアンカー。ID から、それを書いたファイルとアンカーへの対応 (同じ ID が 2 つあれば 2 つ)
    anchors: dict[str, list[tuple[str, markdown.Anchor]]] = field(default_factory=dict)
    documents: dict[str, markdown.Document] = field(default_factory=dict)  # パスから、読んだ Markdown への対応

    # 比べる形のラベルから、その候補の参照先への対応。最初の candidates の呼び出しで、参照先の一覧から 1 度だけ作る
    _by_label: dict[str, list[Target]] | None = field(default=None, repr=False)

    def candidates(self, label: str) -> list[Target]:
        if self._by_label is None:
            self._by_label = {}
            for target in sorted(self.targets.values(), key=lambda t: t.id):
                for key in target.labels():
                    self._by_label.setdefault(key, []).append(target)
        return list(self._by_label.get(markdown.normalize_label(label), []))

    def file(self, path: str) -> HandwrittenFile | None:
        for handwritten in self.files:
            if handwritten.path == path:
                return handwritten
        return None


def section_name(file_id: str, anchor: str) -> str | None:
    """節のアンカーの名前。file_id のファイルの節のアンカーの形 (<ファイルの ID>-h-<名前>) でなければ None。"""
    prefix = f"{file_id}-{names.SECTION.symbol}-"
    if not anchor.startswith(prefix):
        return None
    name = anchor[len(prefix) :]
    return name if names.is_name(name) else None


def read_markdown(path: Path) -> markdown.Document:
    return markdown.parse(generated_header.read_file(path).text)


class _Finder:
    def __init__(self, root: Path, project: Project):
        self.root = root
        self.project = project
        self.index = Index()
        self.problems: list[Problem] = []

    def problem(self, path: str, message: str, line: int | None = None, column: int | None = None) -> None:
        self.problems.append(Problem("b", path, message, line, column))

    def find(self) -> None:
        for domain in self.project.domains:
            self.find_in_domain(domain)
        self.read_anchors()
        self.add_targets()

    def find_in_domain(self, domain: Domain) -> None:
        directory = self.root / domain.dir
        kinds = "・".join(names.HANDWRITTEN_FILE_KINDS.values())
        # 直下のファイルを先に、同じ深さはパスの文字コードの順に
        found = sorted(directory.rglob("*.md"), key=lambda p: (len(p.relative_to(directory).parts), p.as_posix()))
        for path in found:
            relative = path.relative_to(directory)
            if any(part.startswith(".") for part in relative.parts) or not path.is_file():
                continue
            path_rel = rel(self.root, path)
            if len(relative.parts) == 1:
                if relative.name in GENERATED_NAMES:
                    continue
                symbol = relative.stem
                if symbol not in names.HANDWRITTEN_FILE_KINDS:
                    self.problem(
                        path_rel,
                        f"ドメインのディレクトリの直下に書ける手書きの Markdown は {kinds} だけ",
                    )
                    continue
                self.add_file(path, path_rel, domain, symbol, None)
                continue
            parent = relative.parts[0]
            if len(relative.parts) == 2 and parent in names.HANDWRITTEN_FILE_KINDS:
                child = relative.stem
                if not names.is_name(child):
                    self.problem(path_rel, f"子のファイルの名前 {child} が snake_case でない")
                    continue
                self.add_file(path, path_rel, domain, parent, child)
                continue
            if parent in names.HANDWRITTEN_FILE_KINDS:
                self.problem(path_rel, f"子のファイルは、ディレクトリ {parent}/ の直下にだけ書ける (サブディレクトリは 1 階層だけ)")
            else:
                directories = "・".join(f"{s}/" for s in names.HANDWRITTEN_FILE_KINDS)
                self.problem(
                    path_rel,
                    f"ドメインのサブディレクトリに書ける手書きの Markdown は、ディレクトリ {directories} の直下の子のファイルだけ",
                )

    def add_file(self, path: Path, path_rel: str, domain: Domain, symbol: str, child: str | None) -> None:
        document = read_markdown(path)
        self.index.documents[path_rel] = document
        self.index.files.append(HandwrittenFile(path_rel, domain, symbol, child, document))

    def read_anchors(self) -> None:
        domains_dir = self.root / DOMAINS_DIR
        if not domains_dir.is_dir():
            return
        for path in sorted(domains_dir.rglob("*.md")):
            relative = path.relative_to(domains_dir)
            if any(part.startswith(".") for part in relative.parts) or not path.is_file():
                continue
            path_rel = rel(self.root, path)
            document = self.index.documents.get(path_rel)
            if document is None:
                document = read_markdown(path)
                self.index.documents[path_rel] = document
            for anchor in document.anchors:
                self.index.anchors.setdefault(anchor.name, []).append((path_rel, anchor))

    def add_target(
        self, target_id: str, parts: list[str], name: str | None, path: str, abbreviated: str | None = None
    ) -> None:
        """path のファイルに target_id のアンカーがあれば、参照先にする。"""
        if any(found == path for found, _ in self.index.anchors.get(target_id, [])):
            self.index.targets[target_id] = Target(target_id, path, parts, name, abbreviated)

    def add_targets(self) -> None:
        for domain in self.project.domains:
            # ファイルは、生成する側 (モジュール generate) の対応で決める
            self.add_target(domain.id, [domain.full_name()], None, f"{domain.dir}/{README}")
            for symbol, file_name in names.FILE_KINDS.items():
                file_id = names.build_id([Part("d", domain.name), Part(symbol, None)])
                parts = [domain.full_name(), names.format_part(symbol, file_name)]
                self.add_target(file_id, parts, f"`{file_name}`", file_path(domain, symbol))
            for entry in domain.entries():
                parts = [domain.full_name()] + [names.format_part(e.symbol, e.name_ja) for e in entry.lineage()]
                abbreviated = None
                if entry.symbol in names.ABBREVIATIONS:
                    abbreviated = names.format_part(entry.symbol, entry.name_ja, abbreviated=True)
                self.add_target(entry.id, parts, entry.name_ja, entry_file(entry), abbreviated)
        for handwritten in self.index.files:
            document = handwritten.document
            first = document.first_nonblank()
            file_anchor = next((a for a in document.anchors if a.line == first), None)
            if file_anchor is not None and file_anchor.name == handwritten.id:
                self.add_target(handwritten.id, handwritten.parts(), f"`{handwritten.display}`", handwritten.path)
            for anchor in document.anchors:
                if section_name(handwritten.id, anchor.name) is None:
                    continue
                following = document.next_nonblank(anchor.line)
                heading = document.heading_at(following) if following else None
                if heading is None or not heading.atx or heading.level < 2:
                    continue
                parts = handwritten.parts() + [names.format_part(names.SECTION.symbol, heading.text)]
                self.add_target(anchor.name, parts, heading.text, handwritten.path)


def load_documents(root: Path, project: Project) -> tuple[Index, list[Problem]]:
    """手書きの Markdown を見つけ、参照先の一覧を作る。受け付けない名前と場所の Markdown は、検査 b の問題として返す。"""
    finder = _Finder(root, project)
    finder.find()
    return finder.index, finder.problems
"""手書きの Markdown の参照の読み取り。

検査 i (Markdown のリンク)・検査 c-2・サブコマンド refs が使う。手書きのファイルごとに、本文でラベルを使った箇所から、
参照している ID と、その箇所の行が属する ID を求める。決めた経緯は Issue #198 のコメント
(https://github.com/akm/claude-plugins/issues/198#issuecomment-6853737355)。要点:
  - 参照している ID は、同じファイルの定義の行の href の「#」の後ろ。参照先のアンカーがあるかどうかは見ない
    (アンカーが無いことは検査 b が報告する。refs は、アンカーが無い ID も探す)
  - 外部の URL (http://・https://) を指す定義の行と、定義の行の無いラベルは、参照にしない
  - 行が属する ID は、その行を含む最も内側のアンカー付きの節の ID。節の範囲は、アンカーを付けた見出しから、
    同じ階層か上の階層の次の見出しの手前まで。どのアンカー付きの節にも入らない行は、ファイルの ID に属する
  - 定義の行だけがあって本文で使われていないラベルも、定義の行の位置の参照として返す (in_body が False)
"""

from dataclasses import dataclass

from . import markdown
from .documents import HandwrittenFile, Index, section_name
from .links import is_external, strip_angle


@dataclass(frozen=True)
class Reference:
    file: HandwrittenFile
    line: int  # 本文の参照なら最初の「[」の行、定義の行だけなら定義の行
    column: int
    written: str  # 書いたとおりの形 ([ラベル]・[文][ラベル]・[ラベル][])
    target_id: str  # 定義の行の href の「#」の後ろ
    definition: markdown.Definition
    owner_id: str  # この行が属する ID
    in_body: bool  # 本文の参照なら True。定義の行だけがあって本文で使われていないラベルなら False

    @property
    def path(self) -> str:
        return self.file.path


@dataclass(frozen=True)
class _Section:
    id: str
    start: int  # 見出しの行
    end: int  # 範囲の最後の行 (この行を含む)


def _sections(handwritten: HandwrittenFile) -> list[_Section]:
    """アンカー付きの節と、その行の範囲。"""
    document = handwritten.document
    headings = sorted(document.headings, key=lambda h: h.line)
    sections: list[_Section] = []
    for anchor in document.anchors:
        if section_name(handwritten.id, anchor.name) is None:
            continue
        following = document.next_nonblank(anchor.line)
        heading = document.heading_at(following) if following else None
        if heading is None or not heading.atx or heading.level < 2:
            continue  # 節のアンカーにならない (検査 b が報告する)
        end = len(document.lines)
        for other in headings:
            if other.line > heading.line and other.level <= heading.level:
                end = other.line - 1
                break
        sections.append(_Section(anchor.name, heading.line, end))
    return sections


def owner_of(handwritten: HandwrittenFile, line: int, sections: list[_Section] | None = None) -> str:
    """line (1 から数える) が属する ID。"""
    if sections is None:
        sections = _sections(handwritten)
    containing = [s for s in sections if s.start <= line <= s.end]
    if not containing:
        return handwritten.id
    return max(containing, key=lambda s: s.start).id


def _written(reference: markdown.Reference) -> str:
    if reference.form == "full":
        return f"[{reference.text}][{reference.label}]"
    if reference.form == "collapsed":
        return f"[{reference.text}][]"
    return f"[{reference.text}]"


def file_references(handwritten: HandwrittenFile) -> list[Reference]:
    """1 つの手書きのファイルの参照。本文の参照を行と列の順に、その後に本文で使われていない定義の行を並べる。"""
    document = handwritten.document
    sections = _sections(handwritten)
    definitions: dict[str, markdown.Definition] = {}
    for definition in document.definitions:
        definitions.setdefault(markdown.normalize_label(definition.label), definition)

    def target_of(definition: markdown.Definition) -> str | None:
        if is_external(definition.destination):
            return None
        _, sep, fragment = strip_angle(definition.destination).partition("#")
        return fragment if sep and fragment else None

    found: list[Reference] = []
    used: set[str] = set()
    for reference in document.references:
        key = markdown.normalize_label(reference.label)
        used.add(key)
        definition = definitions.get(key)
        if definition is None:
            continue
        target = target_of(definition)
        if target is None:
            continue
        found.append(
            Reference(
                handwritten, reference.line, reference.column, _written(reference), target, definition,
                owner_of(handwritten, reference.line, sections), True,
            )
        )
    images = {markdown.normalize_label(label) for label in document.image_labels}
    for key, definition in definitions.items():
        if key in used or key in images:
            continue
        target = target_of(definition)
        if target is None:
            continue
        found.append(
            Reference(
                handwritten, definition.line, definition.column, f"[{definition.label}]", target, definition,
                owner_of(handwritten, definition.line, sections), False,
            )
        )
    return found


def all_references(index: Index) -> list[Reference]:
    """すべての手書きのファイルの参照。パスの文字コードの順。"""
    found: list[Reference] = []
    for handwritten in sorted(index.files, key=lambda f: f.path):
        found += file_references(handwritten)
    return found

