@dataclass
class Index:
    files: list[HandwrittenFile] = field(default_factory=list)
    targets: dict[str, Target] = field(default_factory=dict)
    # すべての Markdown のアンカー。ID から、それを書いたファイルとアンカーへの対応 (同じ ID が 2 つあれば 2 つ)
    anchors: dict[str, list[tuple[str, markdown.Anchor]]] = field(default_factory=dict)
    documents: dict[str, markdown.Document] = field(default_factory=dict)  # パスから、読んだ Markdown への対応

    # 比べる形のラベルから、その候補の参照先への対応。最初の candidates の呼び出しで、参照先の一覧から 1 度だけ作る
    _by_label: dict[str, list[Target]] | None = field(default=None, repr=False)

    def candidates(self, label: str) -> list[Target]:
        if self._by_label is None:
            self._by_label = {}
            for target in sorted(self.targets.values(), key=lambda t: t.id):
                for key in target.labels():
                    self._by_label.setdefault(key, []).append(target)
        return list(self._by_label.get(markdown.normalize_label(label), []))

    def file(self, path: str) -> HandwrittenFile | None:
        for handwritten in self.files:
            if handwritten.path == path:
                return handwritten
        return None


def section_name(file_id: str, anchor: str) -> str | None:
    """節のアンカーの名前。file_id のファイルの節のアンカーの形 (<ファイルの ID>-h-<名前>) でなければ None。"""
    prefix = f"{file_id}-{names.SECTION.symbol}-"
    if not anchor.startswith(prefix):
        return None
    name = anchor[len(prefix) :]
    return name if names.is_name(name) else None


def read_markdown(path: Path) -> markdown.Document:
    return markdown.parse(generated_header.read_file(path).text)


class _Finder:
    def __init__(self, root: Path, project: Project):
        self.root = root
        self.project = project
        self.index = Index()
        self.problems: list[Problem] = []

    def problem(self, path: str, message: str, line: int | None = None, column: int | None = None) -> None:
        self.problems.append(Problem("b", path, message, line, column))

    def find(self) -> None:
        for domain in self.project.domains:
            self.find_in_domain(domain)
        self.read_anchors()
        self.add_targets()

    def find_in_domain(self, domain: Domain) -> None:
        directory = self.root / domain.dir
        kinds = "・".join(names.HANDWRITTEN_FILE_KINDS.values())
        # 直下のファイルを先に、同じ深さはパスの文字コードの順に
        found = sorted(directory.rglob("*.md"), key=lambda p: (len(p.relative_to(directory).parts), p.as_posix()))
        for path in found:
            relative = path.relative_to(directory)
            if any(part.startswith(".") for part in relative.parts) or not path.is_file():
                continue
            path_rel = rel(self.root, path)
            if len(relative.parts) == 1:
                if relative.name in GENERATED_NAMES:
                    continue
                symbol = relative.stem
                if symbol not in names.HANDWRITTEN_FILE_KINDS:
                    self.problem(
                        path_rel,
                        f"ドメインのディレクトリの直下に書ける手書きの Markdown は {kinds} だけ",
                    )
                    continue
                self.add_file(path, path_rel, domain, symbol, None)
                continue
            parent = relative.parts[0]
            if len(relative.parts) == 2 and parent in names.HANDWRITTEN_FILE_KINDS:
                child = relative.stem
                if not names.is_name(child):
                    self.problem(path_rel, f"子のファイルの名前 {child} が snake_case でない")
                    continue
                self.add_file(path, path_rel, domain, parent, child)
                continue
            if parent in names.HANDWRITTEN_FILE_KINDS:
                self.problem(path_rel, f"子のファイルは、ディレクトリ {parent}/ の直下にだけ書ける (サブディレクトリは 1 階層だけ)")
            else:
                directories = "・".join(f"{s}/" for s in names.HANDWRITTEN_FILE_KINDS)
                self.problem(
                    path_rel,
                    f"ドメインのサブディレクトリに書ける手書きの Markdown は、ディレクトリ {directories} の直下の子のファイルだけ",
                )

    def add_file(self, path: Path, path_rel: str, domain: Domain, symbol: str, child: str | None) -> None:
        document = read_markdown(path)
        self.index.documents[path_rel] = document
        self.index.files.append(HandwrittenFile(path_rel, domain, symbol, child, document))

    def read_anchors(self) -> None:
        domains_dir = self.root / DOMAINS_DIR
        if not domains_dir.is_dir():
            return
        for path in sorted(domains_dir.rglob("*.md")):
            relative = path.relative_to(domains_dir)
            if any(part.startswith(".") for part in relative.parts) or not path.is_file():
                continue
            path_rel = rel(self.root, path)
            document = self.index.documents.get(path_rel)
            if document is None:
                document = read_markdown(path)
                self.index.documents[path_rel] = document
            for anchor in document.anchors:
                self.index.anchors.setdefault(anchor.name, []).append((path_rel, anchor))

    def add_target(
        self, target_id: str, parts: list[str], name: str | None, path: str, abbreviated: str | None = None
    ) -> None:
        """path のファイルに target_id のアンカーがあれば、参照先にする。"""
        if any(found == path for found, _ in self.index.anchors.get(target_id, [])):
            self.index.targets[target_id] = Target(target_id, path, parts, name, abbreviated)

    def add_targets(self) -> None:
        for domain in self.project.domains:
            # ファイルは、生成する側 (モジュール generate) の対応で決める
            self.add_target(domain.id, [domain.full_name()], None, f"{domain.dir}/{README}")
            for symbol, file_name in names.FILE_KINDS.items():
                file_id = names.build_id([Part("d", domain.name), Part(symbol, None)])
                parts = [domain.full_name(), names.format_part(symbol, file_name)]
                self.add_target(file_id, parts, f"`{file_name}`", file_path(domain, symbol))
            for entry in domain.entries():
                parts = [domain.full_name()] + [names.format_part(e.symbol, e.name_ja) for e in entry.lineage()]
                abbreviated = None
                if entry.symbol in names.ABBREVIATIONS:
                    abbreviated = names.format_part(entry.symbol, entry.name_ja, abbreviated=True)
                self.add_target(entry.id, parts, entry.name_ja, entry_file(entry), abbreviated)
        for handwritten in self.index.files:
            document = handwritten.document
            first = document.first_nonblank()
            file_anchor = next((a for a in document.anchors if a.line == first), None)
            if file_anchor is not None and file_anchor.name == handwritten.id:
                self.add_target(handwritten.id, handwritten.parts(), f"`{handwritten.display}`", handwritten.path)
            for anchor in document.anchors:
                if section_name(handwritten.id, anchor.name) is None:
                    continue
                following = document.next_nonblank(anchor.line)
                heading = document.heading_at(following) if following else None
                if heading is None or not heading.atx or heading.level < 2:
                    continue
                parts = handwritten.parts() + [names.format_part(names.SECTION.symbol, heading.text)]
                self.add_target(anchor.name, parts, heading.text, handwritten.path)


def load_documents(root: Path, project: Project) -> tuple[Index, list[Problem]]:
    """手書きの Markdown を見つけ、参照先の一覧を作る。受け付けない名前と場所の Markdown は、検査 b の問題として返す。"""
    finder = _Finder(root, project)
    finder.find()
    return finder.index, finder.problems
"""手書きの Markdown の参照の読み取り。

検査 i (Markdown のリンク)・検査 c-2・サブコマンド refs が使う。手書きのファイルごとに、本文でラベルを使った箇所から、
参照している ID と、その箇所の行が属する ID を求める。決めた経緯は Issue #198 のコメント
(https://github.com/akm/claude-plugins/issues/198#issuecomment-6853737355)。要点:
  - 参照している ID は、同じファイルの定義の行の href の「#」の後ろ。参照先のアンカーがあるかどうかは見ない
    (アンカーが無いことは検査 b が報告する。refs は、アンカーが無い ID も探す)
  - 外部の URL (http://・https://) を指す定義の行と、定義の行の無いラベルは、参照にしない
  - 行が属する ID は、その行を含む最も内側のアンカー付きの節の ID。節の範囲は、アンカーを付けた見出しから、
    同じ階層か上の階層の次の見出しの手前まで。どのアンカー付きの節にも入らない行は、ファイルの ID に属する
  - 定義の行だけがあって本文で使われていないラベルも、定義の行の位置の参照として返す (in_body が False)
"""

from dataclasses import dataclass

from . import markdown
from .documents import HandwrittenFile, Index, section_name
from .links import is_external, strip_angle


@dataclass(frozen=True)
class Reference:
    file: HandwrittenFile
    line: int  # 本文の参照なら最初の「[」の行、定義の行だけなら定義の行
    column: int
    written: str  # 書いたとおりの形 ([ラベル]・[文][ラベル]・[ラベル][])
    target_id: str  # 定義の行の href の「#」の後ろ
    definition: markdown.Definition
    owner_id: str  # この行が属する ID
    in_body: bool  # 本文の参照なら True。定義の行だけがあって本文で使われていないラベルなら False

    @property
    def path(self) -> str:
        return self.file.path


@dataclass(frozen=True)
class _Section:
    id: str
    start: int  # 見出しの行
    end: int  # 範囲の最後の行 (この行を含む)


def _sections(handwritten: HandwrittenFile) -> list[_Section]:
    """アンカー付きの節と、その行の範囲。"""
    document = handwritten.document
    headings = sorted(document.headings, key=lambda h: h.line)
    sections: list[_Section] = []
    for anchor in document.anchors:
        if section_name(handwritten.id, anchor.name) is None:
            continue
        following = document.next_nonblank(anchor.line)
        heading = document.heading_at(following) if following else None
        if heading is None or not heading.atx or heading.level < 2:
            continue  # 節のアンカーにならない (検査 b が報告する)
        end = len(document.lines)
        for other in headings:
            if other.line > heading.line and other.level <= heading.level:
                end = other.line - 1
                break
        sections.append(_Section(anchor.name, heading.line, end))
    return sections


def owner_of(handwritten: HandwrittenFile, line: int, sections: list[_Section] | None = None) -> str:
    """line (1 から数える) が属する ID。"""
    if sections is None:
        sections = _sections(handwritten)
    containing = [s for s in sections if s.start <= line <= s.end]
    if not containing:
        return handwritten.id
    return max(containing, key=lambda s: s.start).id


def _written(reference: markdown.Reference) -> str:
    if reference.form == "full":
        return f"[{reference.text}][{reference.label}]"
    if reference.form == "collapsed":
        return f"[{reference.text}][]"
    return f"[{reference.text}]"


def file_references(handwritten: HandwrittenFile) -> list[Reference]:
    """1 つの手書きのファイルの参照。本文の参照を行と列の順に、その後に本文で使われていない定義の行を並べる。"""
    document = handwritten.document
    sections = _sections(handwritten)
    definitions: dict[str, markdown.Definition] = {}
    for definition in document.definitions:
        definitions.setdefault(markdown.normalize_label(definition.label), definition)

    def target_of(definition: markdown.Definition) -> str | None:
        if is_external(definition.destination):
            return None
        _, sep, fragment = strip_angle(definition.destination).partition("#")
        return fragment if sep and fragment else None

    found: list[Reference] = []
    used: set[str] = set()
    for reference in document.references:
        key = markdown.normalize_label(reference.label)
        used.add(key)
        definition = definitions.get(key)
        if definition is None:
            continue
        target = target_of(definition)
        if target is None:
            continue
        found.append(
            Reference(
                handwritten, reference.line, reference.column, _written(reference), target, definition,
                owner_of(handwritten, reference.line, sections), True,
            )
        )
    images = {markdown.normalize_label(label) for label in document.image_labels}
    for key, definition in definitions.items():
        if key in used or key in images:
            continue
        target = target_of(definition)
        if target is None:
            continue
        found.append(
            Reference(
                handwritten, definition.line, definition.column, f"[{definition.label}]", target, definition,
                owner_of(handwritten, definition.line, sections), False,
            )
        )
    return found


def all_references(index: Index) -> list[Reference]:
    """すべての手書きのファイルの参照。パスの文字コードの順。"""
    found: list[Reference] = []
    for handwritten in sorted(index.files, key=lambda f: f.path):
        found += file_references(handwritten)
    return found

content.content:
"""サブコマンド check が実行する検査と、検査 a (生成し直して差分が無い)。

検査の群 (決定の一覧の問 12 (3)):
  軽い群 (--light。デフォルト)  文書と YAML だけで実行できる検査。この版では a・b・c-2・h・i・k
  重い群 (--heavy)              データベースなどが要る検査。この版には無い
--all は両方、--only <検査> は 1 つだけを実行する。
検査 h (YAML の形式) に誤りがあると、定義の一覧と完全な名前が正しく作れないので、検査 a・b・i は実行せず、そのことを報告する。
検査 c-2 も、検査 b が確認するリンクの上で数えるので、検査 b と同じく実行しない (決めた経緯は Issue #198 のコメントの 6)。
検査 k (手書きの Markdown の行数) は YAML を使わないので、いつも実行する。
"""

import difflib
from dataclasses import dataclass, field
from pathlib import Path

from . import generated_header
from .cycles import check_cycles
from .direction import check_direction, check_markdown_direction
from .documents import load_documents
from .domains import Project, load_project
from .generate import GITATTRIBUTES_PATH, HANDWRITTEN_MESSAGE, generated_files, handwritten_fix, is_handwritten, render_project
from .length import check_length
from .links import check_links
from .problems import Problem

LIGHT = ("a", "b", "c-2", "h", "i", "k")
HEAVY: tuple[str, ...] = ()
ALL = LIGHT + HEAVY


@dataclass
class CheckResult:
    checks: tuple[str, ...]  # 実行するよう指定された検査
    problems: list[Problem] = field(default_factory=list)
    skipped: list[str] = field(default_factory=list)  # 検査 h の誤りのため実行しなかった検査

    @property
    def ok(self) -> bool:
        return not self.problems and not self.skipped


def check_generated(root: Path, project: Project) -> list[Problem]:
    """検査 a: 生成し直した内容と、今のファイルを比べる。"""
    problems: list[Problem] = []
    outputs = render_project(project)
    for relative, expected in outputs.items():
        header = generated_header.read_header(expected)
        if relative == GITATTRIBUTES_PATH:
            how = f"このファイルを直接編集せず、{header.command} を実行する。{generated_header.GITATTRIBUTES_GUIDE}"
        else:
            how = f"このファイルを直接編集せず、生成元 {header.source} の YAML を直して {header.command} を実行する"
        path = root / relative
        if not path.is_file():
            problems.append(Problem("a", relative, f"生成するはずのファイルが無い。{header.command} を実行する"))
            continue
        content = generated_header.read_file(path)
        if is_handwritten(content):
            problems.append(Problem("a", relative, f"{HANDWRITTEN_MESSAGE}。{handwritten_fix(relative)}"))
            continue
        if content.matches(expected):
            continue
        if content.header is None:
            # 先頭の記述が無く、手で書いたファイルでもない (空白と BOM だけの) ファイル。YAML の修正は要らない
            problems.append(Problem("a", relative, f"生成したファイルの中身が無い。{header.command} を実行する"))
            continue
        actual = content.text
        if actual == expected:
            # 読んだ内容は同じで、BOM か UTF-8 として読めないバイトだけが違う。YAML の修正は要らない
            problems.append(
                Problem(
                    "a", relative,
                    f"生成し直した内容と違う (BOM か、UTF-8 として読めないバイトがある)。{header.command} を実行する",
                )
            )
            continue
        diff = "".join(
            difflib.unified_diff(
                actual.splitlines(keepends=True),
                expected.splitlines(keepends=True),
                fromfile=f"{relative} (今のファイル)",
                tofile=f"{relative} (生成し直した内容)",
            )
        )
        problems.append(Problem("a", relative, f"生成し直した内容と違う。{how}", detail=diff))
    for relative, header in generated_files(root).items():
        if relative in outputs:
            continue
        if header.source and not (root / header.source).exists():
            message = f"生成元 {header.source} が無い。このファイルを消すか、生成元を戻す"
        else:
            command = header.command or generated_header.GENERATE_COMMAND
            message = f"生成し直すと消えるファイルが残っている。{command} を実行して消す"
        problems.append(Problem("a", relative, message))
    return problems


def run_checks(root: Path, checks: tuple[str, ...]) -> CheckResult:
    result = CheckResult(checks=checks)
    if not checks:
        return result
    project, yaml_problems = load_project(root)
    if "h" in checks:
        result.problems += yaml_problems
    if "b" in checks or "k" in checks or "i" in checks or "c-2" in checks:
        # ドメインの一覧はディレクトリ名から作るので、YAML に誤りがあっても手書きの Markdown を見つけられる
        index, document_problems = load_documents(root, project)
    if "k" in checks:
        result.problems += check_length(index)
    if yaml_problems:
        result.skipped = [c for c in checks if c in ("a", "b", "c-2", "i")]
        return result
    if "b" in checks:
        result.problems += document_problems + check_links(index)
    if "i" in checks:
        result.problems += check_direction(project) + check_markdown_direction(index)
    if "c-2" in checks:
        result.problems += check_cycles(index)
    if "a" in checks:
        result.problems += check_generated(root, project)
    return result
"""ドメインの YAML から、人が読む Markdown を生成する。

ドメインのディレクトリの直下に README.md・models.md・unclassified_app_terms.md・terms.md を、全体の用語の索引
docs/glossary.md を生成する。生成するファイルの中身の SSOT はプラグインの規則の文書
(ファイル doc-structured/rules/doc-structured-domains.md)。要点:
  - 先頭に、生成したファイルの先頭の記述 (モジュール generated_header) を書く
  - 定義ごとに <a name="ID"></a> と見出しを書く。見出しは「種類 + 日本語名」の後に英語名をコードの書式で書く
  - リンクは reference-style で、ラベルを ID にし、定義の行 [ID]: 相対パス#ID "完全な名前" をファイルの末尾に書く
  - 用語の索引は定義の文を持たず、日本語名の文字コードの順 (同じなら ID の順) に、定義へのリンクを並べる
  - 定義が 1 つも無い種類のファイルは作らない
  - README.md の表には、ドメインのディレクトリの直下にある手書きのファイルを先に、生成したファイルを後に並べる
  - docs/.gitattributes に、生成したファイル (docs/.gitattributes 自身を含む) の merge の設定を書く
  - 生成するファイルの場所に、先頭の記述が無く、空白と BOM 以外の文字があるファイル (手で書いたファイル) があれば、何も書かない (呼び出し元がエラーにする)
同じ入力からは、いつも同じ出力を作る (時刻や環境に依存する値を書かない)。
"""

import posixpath
from pathlib import Path

from . import generated_header, names
from .domains import DOMAINS_DIR, Domain, Entry, Project

GLOSSARY_PATH = "docs/glossary.md"
GITATTRIBUTES_PATH = "docs/.gitattributes"
# 生成したファイルの merge の設定。git の組み込みの merge driver binary は、競合したときに git が ours とする側の内容を残し、
# 競合のマークを入れない (ファイルは競合の状態のまま)。どの側が ours になるかは git のコマンドによって違い、
# 残った内容は古いことがあるので、生成し直してから git add する
GITATTRIBUTES_COMMENT = (
    "# 生成したファイルが競合したときは、git が ours とする側の内容が残る (組み込みの merge driver binary。"
    "どの側が ours になるかは git のコマンドによって違う)。生成し直してから git add する"
)
README = "README.md"
FILE_DESCRIPTIONS = {
    "concept": "概念・境界・不変条件・方針・理由",
    "problem": "問題",
    "design": "設計の判断と短い理由",
    "models": "モデル・属性・値の定義",
    "unclassified_app_terms": "未分類のアプリケーション用語の定義",
    "terms": "このドメインの用語の索引",
}
# 見出しの深さ。モデル 2・属性 3・値 4。未分類のアプリケーション用語は 2
HEADING_LEVELS = {"m": 2, "a": 3, "v": 4, "ut": 2}


def escape_link_text(text: str) -> str:
    return text.replace("\\", "\\\\").replace("[", "\\[").replace("]", "\\]")


def escape_cell(text: str) -> str:
    return text.replace("|", "\\|")


class _Links:
    """1 つのファイルの reference-style のリンクと、末尾に書く定義の行。"""

    def __init__(self, file: str):
        self.file = file
        self.definitions: dict[str, tuple[str, str]] = {}

    def link(self, text: str, target_id: str, target_file: str, title: str) -> str:
        if target_file == self.file:
            href = f"#{target_id}"
        else:
            relative = posixpath.relpath(target_file, posixpath.dirname(self.file))
            href = f"{relative}#{target_id}"
        self.definitions[target_id] = (href, title)
        return f"[{escape_link_text(text)}][{target_id}]"

    def lines(self) -> list[str]:
        return [f'[{label}]: {href} "{title}"' for label, (href, title) in sorted(self.definitions.items())]


def _file_name(symbol: str) -> str:
    return names.FILE_KINDS.get(symbol) or names.HANDWRITTEN_FILE_KINDS[symbol]


def file_path(domain: Domain, symbol: str) -> str:
    return f"{domain.dir}/{_file_name(symbol)}"


def _file_id(domain: Domain, symbol: str) -> str:
    return names.build_id([names.Part("d", domain.name), names.Part(symbol, None)])


def _file_title(domain: Domain, symbol: str) -> str:
    return names.join_parts([domain.full_name(), names.format_part(symbol, _file_name(symbol))])


def entry_file(entry: Entry) -> str:
    symbol = "unclassified_app_terms" if entry.symbol == "ut" else "models"
    return file_path(entry.domain, symbol)


def _entry_link(links: _Links, entry: Entry, text: str) -> str:
    return links.link(text, entry.id, entry_file(entry), entry.full_name())


def _reference_text(entry: Entry, from_domain: Domain) -> str:
    """ほかの定義を指すリンクの表示の文。同じドメインなら「種類 + 名前」、ほかのドメインなら完全な名前。"""
    if entry.domain is from_domain:
        return names.format_part(entry.symbol, entry.name_ja)
    return entry.full_name()


def _document(source: str, anchor: str | None, blocks: list[str], links: _Links) -> str:
    parts = [generated_header.markdown_line(source)]
    if anchor:
        parts.append(f'<a name="{anchor}"></a>')
    text = "\n".join(parts) + "\n\n" + "\n\n".join(blocks)
    definition_lines = links.lines()
    if definition_lines:
        text += "\n\n" + "\n".join(definition_lines)
    return text + "\n"


def _definition_block(entry: Entry, extra: str = "") -> str:
    heading = "#" * HEADING_LEVELS[entry.symbol]
    title = f"{names.format_part(entry.symbol, entry.name_ja)} `{entry.name}`"
    body = entry.definition
    if extra:
        body += extra if body.endswith("。") else f" {extra}"
    return f'<a name="{entry.id}"></a>\n\n{heading} {title}\n\n{body}'


def _referencing_models(project: Project) -> dict[str, list[Entry]]:
    """モデルの ID から、そのモデルを参照するモデルへの対応。定義の並び順で、重複は除く。"""
    result: dict[str, list[Entry]] = {}
    for domain in project.domains:
        for model in domain.models:
            for attribute in model.children:
                target = attribute.refers_to
                if target in project.entries and model not in result.setdefault(target, []):
                    result[target].append(model)
    return result


def render_models(project: Project, domain: Domain, referencing: dict[str, list[Entry]]) -> str:
    path = file_path(domain, "models")
    links = _Links(path)
    blocks = [f"# {domain.full_name()} のモデル"]
    for model in domain.models:
        blocks.append(_definition_block(model))
        users = referencing.get(model.id, [])
        if users:
            listed = "・".join(_entry_link(links, m, _reference_text(m, domain)) for m in users)
            blocks.append(f"このモデルを参照するモデル: {listed}")
        for attribute in model.children:
            extra = ""
            if attribute.refers_to in project.entries:
                target = project.entries[attribute.refers_to]
                extra = "参照先: " + _entry_link(links, target, _reference_text(target, domain))
            blocks.append(_definition_block(attribute, extra))
            for value in attribute.children:
                blocks.append(_definition_block(value))
    return _document(f"{domain.dir}/", _file_id(domain, "models"), blocks, links)


def render_unclassified_app_terms(domain: Domain) -> str:
    path = file_path(domain, "unclassified_app_terms")
    links = _Links(path)
    blocks = [f"# {domain.full_name()} の{names.KINDS['ut'].label}"]
    blocks += [_definition_block(term) for term in domain.terms]
    return _document(f"{domain.dir}/", _file_id(domain, "unclassified_app_terms"), blocks, links)


def _kind_text(entry: Entry) -> str:
    """用語の索引の「種類」の列。ドメインの中の親の「種類 + 名前」と、自分の種類の名前。"""
    parents = [names.format_part(e.symbol, e.name_ja) for e in entry.lineage()[:-1]]
    return names.join_parts([*parents, entry.kind_label])


def _sorted_terms(entries: list[Entry]) -> list[Entry]:
    return sorted(entries, key=lambda e: (e.name_ja, e.id))


def render_terms(domain: Domain) -> str:
    path = file_path(domain, "terms")
    links = _Links(path)
    rows = ["| 用語 | 種類 | 英語名 |", "|---|---|---|"]
    for entry in _sorted_terms(list(domain.entries())):
        term = escape_cell(_entry_link(links, entry, entry.name_ja))
        rows.append(f"| {term} | {escape_cell(_kind_text(entry))} | `{entry.name}` |")
    blocks = [f"# {domain.full_name()} の用語の索引", "\n".join(rows)]
    return _document(f"{domain.dir}/", _file_id(domain, "terms"), blocks, links)


def render_glossary(project: Project) -> str:
    links = _Links(GLOSSARY_PATH)
    rows = ["| 用語 | 種類 | 英語名 | ドメイン |", "|---|---|---|---|"]
    all_entries = [e for d in project.domains for e in d.entries()]
    for entry in _sorted_terms(all_entries):
        domain = entry.domain
        term = escape_cell(_entry_link(links, entry, entry.name_ja))
        domain_link = links.link(f"`{domain.name}`", domain.id, f"{domain.dir}/{README}", domain.full_name())
        rows.append(f"| {term} | {escape_cell(_kind_text(entry))} | `{entry.name}` | {domain_link} |")
    blocks = ["# 用語の索引", "\n".join(rows)]
    return _document(f"{DOMAINS_DIR.as_posix()}/", None, blocks, links)


def render_readme(domain: Domain, files: list[str]) -> str:
    """files は、表に載せるファイルの種類の記号。ドメインのディレクトリの直下にある手書きのファイル (concept・problem・design)
    を先に、このドメインで生成するファイル (models・unclassified_app_terms・terms) を後に並べる。"""
    path = f"{domain.dir}/{README}"
    links = _Links(path)
    blocks = [f"# {domain.full_name()}"]
    if domain.description:
        blocks.append(domain.description)
    if files:
        rows = ["| 文書 | 中身 |", "|---|---|"]
        for symbol in files:
            link = links.link(
                f"`{_file_name(symbol)}`", _file_id(domain, symbol), file_path(domain, symbol),
                _file_title(domain, symbol),
            )
            rows.append(f"| {link} | {FILE_DESCRIPTIONS[symbol]} |")
        blocks.append("\n".join(rows))
    return _document(f"{domain.dir}/", domain.id, blocks, links)


def render_gitattributes(paths: list[str]) -> str:
    """paths は、ディレクトリ docs/ の下の生成するファイルの、リポジトリのルートからの相対パス (docs/.gitattributes を除く)。"""
    base = posixpath.dirname(GITATTRIBUTES_PATH)
    lines = [generated_header.hash_line(f"{DOMAINS_DIR.as_posix()}/"), GITATTRIBUTES_COMMENT]
    for path in sorted([*paths, GITATTRIBUTES_PATH]):
        if not path.startswith(f"{base}/"):
            raise ValueError(f"ディレクトリ {base}/ の外のファイルは {GITATTRIBUTES_PATH} に書けない: {path}")
        lines.append(f"/{posixpath.relpath(path, base)} merge=binary")
    return "\n".join(lines) + "\n"


def render_project(project: Project) -> dict[str, str]:
    """生成するファイルの、リポジトリのルートからの相対パスと内容。"""
    outputs: dict[str, str] = {}
    referencing = _referencing_models(project)
    for domain in project.domains:
        # 手書きのファイルは、今あるものを表に載せる (足したり消したりすると、検査 a が README.md の生成し直しを求める)
        files = [s for s in names.HANDWRITTEN_FILE_KINDS if (project.root / file_path(domain, s)).is_file()]
        if domain.models:
            outputs[file_path(domain, "models")] = render_models(project, domain, referencing)
            files.append("models")
        if domain.terms:
            outputs[file_path(domain, "unclassified_app_terms")] = render_unclassified_app_terms(domain)
            files.append("unclassified_app_terms")
        if domain.models or domain.terms:
            outputs[file_path(domain, "terms")] = render_terms(domain)
            files.append("terms")
        outputs[f"{domain.dir}/{README}"] = render_readme(domain, files)
    if any(d.models or d.terms for d in project.domains):
        outputs[GLOSSARY_PATH] = render_glossary(project)
    if outputs:
        outputs[GITATTRIBUTES_PATH] = render_gitattributes(list(outputs))
    return dict(sorted(outputs.items()))


def generated_files(root: Path) -> dict[str, generated_header.Header]:
    """ディレクトリ docs/ の下の、先頭の記述を持つファイル (生成したファイル) と、その記述。

    調べるのは、拡張子が .md と .yaml のファイルと、名前が .gitattributes のファイル。
    """
    found: dict[str, generated_header.Header] = {}
    docs = root / "docs"
    if not docs.is_dir():
        return found
    for path in sorted(docs.rglob("*")):
        if not path.is_file() or (path.suffix not in (".md", ".yaml") and path.name != ".gitattributes"):
            continue
        header = generated_header.read_file_header(path)
        if header is not None:
            found[path.relative_to(root).as_posix()] = header
    return found


HANDWRITTEN_MESSAGE = "手で書いたファイルが、生成するファイルの場所にある"


def is_handwritten(content: generated_header.FileContent) -> bool:
    """generated_header.read_file で読んだファイルが、手で書いたファイルか。

    先頭の記述が無く、空白と BOM (U+FEFF) 以外の文字があるファイルを、手で書いたファイルとする。
    空のファイルと、空白と BOM だけのファイル (生成したファイルが中身ごと消えたものなど) は、失う内容が無いので含めない。
    """
    return content.header is None and not content.is_blank


class HandwrittenFilesError(Exception):
    """生成するファイルの場所に手で書いたファイルがあるので、何も書かなかったことを表す。"""

    def __init__(self, paths: list[str]):
        super().__init__(f"{HANDWRITTEN_MESSAGE}: {', '.join(paths)}")
        self.paths = paths


def handwritten_fix(relative: str) -> str:
    """手で書いたファイルが生成するファイルの場所にあるときの直し方。"""
    if relative == GITATTRIBUTES_PATH:
        return (
            "手で書いた行を、パターンをリポジトリのルートからの相対に書き換えて (docs/.gitattributes のパターンは docs/ からの相対)、"
            "リポジトリのルートの .gitattributes に移してから、このファイルを消す"
        )
    return "ファイルの名前を変える。または、内容を手書きの文書に移してから、このファイルを消す"


def write_outputs(root: Path, outputs: dict[str, str]) -> tuple[list[str], list[str]]:
    """生成したファイルを書き、生成し直すと無くなるファイルを消す。書いたファイルと消したファイルを返す。

    消すのは、先頭の記述を持つファイル (生成したファイル) だけ。手書きのファイルは消さない。
    内容が同じファイルは書かない。生成するファイルの場所に手で書いたファイルがあれば、何も書かずに
    HandwrittenFilesError を送出する (呼び出し元が、そのパスの配列から利用者にエラーを伝える)。
    """
    # 生成するファイルの場所にある今のファイルを 1 回だけ読み、手で書いたファイルの判定と書く前の比較の両方に使う
    existing = {
        relative: generated_header.read_file(root / relative) for relative in outputs if (root / relative).is_file()
    }
    handwritten = [relative for relative, current in existing.items() if is_handwritten(current)]
    if handwritten:
        raise HandwrittenFilesError(handwritten)
    written: list[str] = []
    for relative, content in outputs.items():
        path = root / relative
        # 検査 a と同じ判定で比べる (改行の違いだけなら書かず、BOM や UTF-8 として読めないバイトがあれば上書きする)
        if relative in existing and existing[relative].matches(content):
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        written.append(relative)
    deleted: list[str] = []
    for relative in generated_files(root):
        if relative not in outputs:
            (root / relative).unlink()
            deleted.append(relative)
    return written, deleted

toolUseResult.stdout:
"""サブコマンド check が実行する検査と、検査 a (生成し直して差分が無い)。

検査の群 (決定の一覧の問 12 (3)):
  軽い群 (--light。デフォルト)  文書と YAML だけで実行できる検査。この版では a・b・c-2・h・i・k
  重い群 (--heavy)              データベースなどが要る検査。この版には無い
--all は両方、--only <検査> は 1 つだけを実行する。
検査 h (YAML の形式) に誤りがあると、定義の一覧と完全な名前が正しく作れないので、検査 a・b・i は実行せず、そのことを報告する。
検査 c-2 も、検査 b が確認するリンクの上で数えるので、検査 b と同じく実行しない (決めた経緯は Issue #198 のコメントの 6)。
検査 k (手書きの Markdown の行数) は YAML を使わないので、いつも実行する。
"""

import difflib
from dataclasses import dataclass, field
from pathlib import Path

from . import generated_header
from .cycles import check_cycles
from .direction import check_direction, check_markdown_direction
from .documents import load_documents
from .domains import Project, load_project
from .generate import GITATTRIBUTES_PATH, HANDWRITTEN_MESSAGE, generated_files, handwritten_fix, is_handwritten, render_project
from .length import check_length
from .links import check_links
from .problems import Problem

LIGHT = ("a", "b", "c-2", "h", "i", "k")
HEAVY: tuple[str, ...] = ()
ALL = LIGHT + HEAVY


@dataclass
class CheckResult:
    checks: tuple[str, ...]  # 実行するよう指定された検査
    problems: list[Problem] = field(default_factory=list)
    skipped: list[str] = field(default_factory=list)  # 検査 h の誤りのため実行しなかった検査

    @property
    def ok(self) -> bool:
        return not self.problems and not self.skipped


def check_generated(root: Path, project: Project) -> list[Problem]:
    """検査 a: 生成し直した内容と、今のファイルを比べる。"""
    problems: list[Problem] = []
    outputs = render_project(project)
    for relative, expected in outputs.items():
        header = generated_header.read_header(expected)
        if relative == GITATTRIBUTES_PATH:
            how = f"このファイルを直接編集せず、{header.command} を実行する。{generated_header.GITATTRIBUTES_GUIDE}"
        else:
            how = f"このファイルを直接編集せず、生成元 {header.source} の YAML を直して {header.command} を実行する"
        path = root / relative
        if not path.is_file():
            problems.append(Problem("a", relative, f"生成するはずのファイルが無い。{header.command} を実行する"))
            continue
        content = generated_header.read_file(path)
        if is_handwritten(content):
            problems.append(Problem("a", relative, f"{HANDWRITTEN_MESSAGE}。{handwritten_fix(relative)}"))
            continue
        if content.matches(expected):
            continue
        if content.header is None:
            # 先頭の記述が無く、手で書いたファイルでもない (空白と BOM だけの) ファイル。YAML の修正は要らない
            problems.append(Problem("a", relative, f"生成したファイルの中身が無い。{header.command} を実行する"))
            continue
        actual = content.text
        if actual == expected:
            # 読んだ内容は同じで、BOM か UTF-8 として読めないバイトだけが違う。YAML の修正は要らない
            problems.append(
                Problem(
                    "a", relative,
                    f"生成し直した内容と違う (BOM か、UTF-8 として読めないバイトがある)。{header.command} を実行する",
                )
            )
            continue
        diff = "".join(
            difflib.unified_diff(
                actual.splitlines(keepends=True),
                expected.splitlines(keepends=True),
                fromfile=f"{relative} (今のファイル)",
                tofile=f"{relative} (生成し直した内容)",
            )
        )
        problems.append(Problem("a", relative, f"生成し直した内容と違う。{how}", detail=diff))
    for relative, header in generated_files(root).items():
        if relative in outputs:
            continue
        if header.source and not (root / header.source).exists():
            message = f"生成元 {header.source} が無い。このファイルを消すか、生成元を戻す"
        else:
            command = header.command or generated_header.GENERATE_COMMAND
            message = f"生成し直すと消えるファイルが残っている。{command} を実行して消す"
        problems.append(Problem("a", relative, message))
    return problems


def run_checks(root: Path, checks: tuple[str, ...]) -> CheckResult:
    result = CheckResult(checks=checks)
    if not checks:
        return result
    project, yaml_problems = load_project(root)
    if "h" in checks:
        result.problems += yaml_problems
    if "b" in checks or "k" in checks or "i" in checks or "c-2" in checks:
        # ドメインの一覧はディレクトリ名から作るので、YAML に誤りがあっても手書きの Markdown を見つけられる
        index, document_problems = load_documents(root, project)
    if "k" in checks:
        result.problems += check_length(index)
    if yaml_problems:
        result.skipped = [c for c in checks if c in ("a", "b", "c-2", "i")]
        return result
    if "b" in checks:
        result.problems += document_problems + check_links(index)
    if "i" in checks:
        result.problems += check_direction(project) + check_markdown_direction(index)
    if "c-2" in checks:
        result.problems += check_cycles(index)
    if "a" in checks:
        result.problems += check_generated(root, project)
    return result
"""ドメインの YAML から、人が読む Markdown を生成する。

ドメインのディレクトリの直下に README.md・models.md・unclassified_app_terms.md・terms.md を、全体の用語の索引
docs/glossary.md を生成する。生成するファイルの中身の SSOT はプラグインの規則の文書
(ファイル doc-structured/rules/doc-structured-domains.md)。要点:
  - 先頭に、生成したファイルの先頭の記述 (モジュール generated_header) を書く
  - 定義ごとに <a name="ID"></a> と見出しを書く。見出しは「種類 + 日本語名」の後に英語名をコードの書式で書く
  - リンクは reference-style で、ラベルを ID にし、定義の行 [ID]: 相対パス#ID "完全な名前" をファイルの末尾に書く
  - 用語の索引は定義の文を持たず、日本語名の文字コードの順 (同じなら ID の順) に、定義へのリンクを並べる
  - 定義が 1 つも無い種類のファイルは作らない
  - README.md の表には、ドメインのディレクトリの直下にある手書きのファイルを先に、生成したファイルを後に並べる
  - docs/.gitattributes に、生成したファイル (docs/.gitattributes 自身を含む) の merge の設定を書く
  - 生成するファイルの場所に、先頭の記述が無く、空白と BOM 以外の文字があるファイル (手で書いたファイル) があれば、何も書かない (呼び出し元がエラーにする)
同じ入力からは、いつも同じ出力を作る (時刻や環境に依存する値を書かない)。
"""

import posixpath
from pathlib import Path

from . import generated_header, names
from .domains import DOMAINS_DIR, Domain, Entry, Project

GLOSSARY_PATH = "docs/glossary.md"
GITATTRIBUTES_PATH = "docs/.gitattributes"
# 生成したファイルの merge の設定。git の組み込みの merge driver binary は、競合したときに git が ours とする側の内容を残し、
# 競合のマークを入れない (ファイルは競合の状態のまま)。どの側が ours になるかは git のコマンドによって違い、
# 残った内容は古いことがあるので、生成し直してから git add する
GITATTRIBUTES_COMMENT = (
    "# 生成したファイルが競合したときは、git が ours とする側の内容が残る (組み込みの merge driver binary。"
    "どの側が ours になるかは git のコマンドによって違う)。生成し直してから git add する"
)
README = "README.md"
FILE_DESCRIPTIONS = {
    "concept": "概念・境界・不変条件・方針・理由",
    "problem": "問題",
    "design": "設計の判断と短い理由",
    "models": "モデル・属性・値の定義",
    "unclassified_app_terms": "未分類のアプリケーション用語の定義",
    "terms": "このドメインの用語の索引",
}
# 見出しの深さ。モデル 2・属性 3・値 4。未分類のアプリケーション用語は 2
HEADING_LEVELS = {"m": 2, "a": 3, "v": 4, "ut": 2}


def escape_link_text(text: str) -> str:
    return text.replace("\\", "\\\\").replace("[", "\\[").replace("]", "\\]")


def escape_cell(text: str) -> str:
    return text.replace("|", "\\|")


class _Links:
    """1 つのファイルの reference-style のリンクと、末尾に書く定義の行。"""

    def __init__(self, file: str):
        self.file = file
        self.definitions: dict[str, tuple[str, str]] = {}

    def link(self, text: str, target_id: str, target_file: str, title: str) -> str:
        if target_file == self.file:
            href = f"#{target_id}"
        else:
            relative = posixpath.relpath(target_file, posixpath.dirname(self.file))
            href = f"{relative}#{target_id}"
        self.definitions[target_id] = (href, title)
        return f"[{escape_link_text(text)}][{target_id}]"

    def lines(self) -> list[str]:
        return [f'[{label}]: {href} "{title}"' for label, (href, title) in sorted(self.definitions.items())]


def _file_name(symbol: str) -> str:
    return names.FILE_KINDS.get(symbol) or names.HANDWRITTEN_FILE_KINDS[symbol]


def file_path(domain: Domain, symbol: str) -> str:
    return f"{domain.dir}/{_file_name(symbol)}"


def _file_id(domain: Domain, symbol: str) -> str:
    return names.build_id([names.Part("d", domain.name), names.Part(symbol, None)])


def _file_title(domain: Domain, symbol: str) -> str:
    return names.join_parts([domain.full_name(), names.format_part(symbol, _file_name(symbol))])


def entry_file(entry: Entry) -> str:
    symbol = "unclassified_app_terms" if entry.symbol == "ut" else "models"
    return file_path(entry.domain, symbol)


def _entry_link(links: _Links, entry: Entry, text: str) -> str:
    return links.link(text, entry.id, entry_file(entry), entry.full_name())


def _reference_text(entry: Entry, from_domain: Domain) -> str:
    """ほかの定義を指すリンクの表示の文。同じドメインなら「種類 + 名前」、ほかのドメインなら完全な名前。"""
    if entry.domain is from_domain:
        return names.format_part(entry.symbol, entry.name_ja)
    return entry.full_name()


def _document(source: str, anchor: str | None, blocks: list[str], links: _Links) -> str:
    parts = [generated_header.markdown_line(source)]
    if anchor:
        parts.append(f'<a name="{anchor}"></a>')
    text = "\n".join(parts) + "\n\n" + "\n\n".join(blocks)
    definition_lines = links.lines()
    if definition_lines:
        text += "\n\n" + "\n".join(definition_lines)
    return text + "\n"


def _definition_block(entry: Entry, extra: str = "") -> str:
    heading = "#" * HEADING_LEVELS[entry.symbol]
    title = f"{names.format_part(entry.symbol, entry.name_ja)} `{entry.name}`"
    body = entry.definition
    if extra:
        body += extra if body.endswith("。") else f" {extra}"
    return f'<a name="{entry.id}"></a>\n\n{heading} {title}\n\n{body}'


def _referencing_models(project: Project) -> dict[str, list[Entry]]:
    """モデルの ID から、そのモデルを参照するモデルへの対応。定義の並び順で、重複は除く。"""
    result: dict[str, list[Entry]] = {}
    for domain in project.domains:
        for model in domain.models:
            for attribute in model.children:
                target = attribute.refers_to
                if target in project.entries and model not in result.setdefault(target, []):
                    result[target].append(model)
    return result


def render_models(project: Project, domain: Domain, referencing: dict[str, list[Entry]]) -> str:
    path = file_path(domain, "models")
    links = _Links(path)
    blocks = [f"# {domain.full_name()} のモデル"]
    for model in domain.models:
        blocks.append(_definition_block(model))
        users = referencing.get(model.id, [])
        if users:
            listed = "・".join(_entry_link(links, m, _reference_text(m, domain)) for m in users)
            blocks.append(f"このモデルを参照するモデル: {listed}")
        for attribute in model.children:
            extra = ""
            if attribute.refers_to in project.entries:
                target = project.entries[attribute.refers_to]
                extra = "参照先: " + _entry_link(links, target, _reference_text(target, domain))
            blocks.append(_definition_block(attribute, extra))
            for value in attribute.children:
                blocks.append(_definition_block(value))
    return _document(f"{domain.dir}/", _file_id(domain, "models"), blocks, links)


def render_unclassified_app_terms(domain: Domain) -> str:
    path = file_path(domain, "unclassified_app_terms")
    links = _Links(path)
    blocks = [f"# {domain.full_name()} の{names.KINDS['ut'].label}"]
    blocks += [_definition_block(term) for term in domain.terms]
    return _document(f"{domain.dir}/", _file_id(domain, "unclassified_app_terms"), blocks, links)


def _kind_text(entry: Entry) -> str:
    """用語の索引の「種類」の列。ドメインの中の親の「種類 + 名前」と、自分の種類の名前。"""
    parents = [names.format_part(e.symbol, e.name_ja) for e in entry.lineage()[:-1]]
    return names.join_parts([*parents, entry.kind_label])


def _sorted_terms(entries: list[Entry]) -> list[Entry]:
    return sorted(entries, key=lambda e: (e.name_ja, e.id))


def render_terms(domain: Domain) -> str:
    path = file_path(domain, "terms")
    links = _Links(path)
    rows = ["| 用語 | 種類 | 英語名 |", "|---|---|---|"]
    for entry in _sorted_terms(list(domain.entries())):
        term = escape_cell(_entry_link(links, entry, entry.name_ja))
        rows.append(f"| {term} | {escape_cell(_kind_text(entry))} | `{entry.name}` |")
    blocks = [f"# {domain.full_name()} の用語の索引", "\n".join(rows)]
    return _document(f"{domain.dir}/", _file_id(domain, "terms"), blocks, links)


def render_glossary(project: Project) -> str:
    links = _Links(GLOSSARY_PATH)
    rows = ["| 用語 | 種類 | 英語名 | ドメイン |", "|---|---|---|---|"]
    all_entries = [e for d in project.domains for e in d.entries()]
    for entry in _sorted_terms(all_entries):
        domain = entry.domain
        term = escape_cell(_entry_link(links, entry, entry.name_ja))
        domain_link = links.link(f"`{domain.name}`", domain.id, f"{domain.dir}/{README}", domain.full_name())
        rows.append(f"| {term} | {escape_cell(_kind_text(entry))} | `{entry.name}` | {domain_link} |")
    blocks = ["# 用語の索引", "\n".join(rows)]
    return _document(f"{DOMAINS_DIR.as_posix()}/", None, blocks, links)


def render_readme(domain: Domain, files: list[str]) -> str:
    """files は、表に載せるファイルの種類の記号。ドメインのディレクトリの直下にある手書きのファイル (concept・problem・design)
    を先に、このドメインで生成するファイル (models・unclassified_app_terms・terms) を後に並べる。"""
    path = f"{domain.dir}/{README}"
    links = _Links(path)
    blocks = [f"# {domain.full_name()}"]
    if domain.description:
        blocks.append(domain.description)
    if files:
        rows = ["| 文書 | 中身 |", "|---|---|"]
        for symbol in files:
            link = links.link(
                f"`{_file_name(symbol)}`", _file_id(domain, symbol), file_path(domain, symbol),
                _file_title(domain, symbol),
            )
            rows.append(f"| {link} | {FILE_DESCRIPTIONS[symbol]} |")
        blocks.append("\n".join(rows))
    return _document(f"{domain.dir}/", domain.id, blocks, links)


def render_gitattributes(paths: list[str]) -> str:
    """paths は、ディレクトリ docs/ の下の生成するファイルの、リポジトリのルートからの相対パス (docs/.gitattributes を除く)。"""
    base = posixpath.dirname(GITATTRIBUTES_PATH)
    lines = [generated_header.hash_line(f"{DOMAINS_DIR.as_posix()}/"), GITATTRIBUTES_COMMENT]
    for path in sorted([*paths, GITATTRIBUTES_PATH]):
        if not path.startswith(f"{base}/"):
            raise ValueError(f"ディレクトリ {base}/ の外のファイルは {GITATTRIBUTES_PATH} に書けない: {path}")
        lines.append(f"/{posixpath.relpath(path, base)} merge=binary")
    return "\n".join(lines) + "\n"


def render_project(project: Project) -> dict[str, str]:
    """生成するファイルの、リポジトリのルートからの相対パスと内容。"""
    outputs: dict[str, str] = {}
    referencing = _referencing_models(project)
    for domain in project.domains:
        # 手書きのファイルは、今あるものを表に載せる (足したり消したりすると、検査 a が README.md の生成し直しを求める)
        files = [s for s in names.HANDWRITTEN_FILE_KINDS if (project.root / file_path(domain, s)).is_file()]
        if domain.models:
            outputs[file_path(domain, "models")] = render_models(project, domain, referencing)
            files.append("models")
        if domain.terms:
            outputs[file_path(domain, "unclassified_app_terms")] = render_unclassified_app_terms(domain)
            files.append("unclassified_app_terms")
        if domain.models or domain.terms:
            outputs[file_path(domain, "terms")] = render_terms(domain)
            files.append("terms")
        outputs[f"{domain.dir}/{README}"] = render_readme(domain, files)
    if any(d.models or d.terms for d in project.domains):
        outputs[GLOSSARY_PATH] = render_glossary(project)
    if outputs:
        outputs[GITATTRIBUTES_PATH] = render_gitattributes(list(outputs))
    return dict(sorted(outputs.items()))


def generated_files(root: Path) -> dict[str, generated_header.Header]:
    """ディレクトリ docs/ の下の、先頭の記述を持つファイル (生成したファイル) と、その記述。

    調べるのは、拡張子が .md と .yaml のファイルと、名前が .gitattributes のファイル。
    """
    found: dict[str, generated_header.Header] = {}
    docs = root / "docs"
    if not docs.is_dir():
        return found
    for path in sorted(docs.rglob("*")):
        if not path.is_file() or (path.suffix not in (".md", ".yaml") and path.name != ".gitattributes"):
            continue
        header = generated_header.read_file_header(path)
        if header is not None:
            found[path.relative_to(root).as_posix()] = header
    return found


HANDWRITTEN_MESSAGE = "手で書いたファイルが、生成するファイルの場所にある"


def is_handwritten(content: generated_header.FileContent) -> bool:
    """generated_header.read_file で読んだファイルが、手で書いたファイルか。

    先頭の記述が無く、空白と BOM (U+FEFF) 以外の文字があるファイルを、手で書いたファイルとする。
    空のファイルと、空白と BOM だけのファイル (生成したファイルが中身ごと消えたものなど) は、失う内容が無いので含めない。
    """
    return content.header is None and not content.is_blank


class HandwrittenFilesError(Exception):
    """生成するファイルの場所に手で書いたファイルがあるので、何も書かなかったことを表す。"""

    def __init__(self, paths: list[str]):
        super().__init__(f"{HANDWRITTEN_MESSAGE}: {', '.join(paths)}")
        self.paths = paths


def handwritten_fix(relative: str) -> str:
    """手で書いたファイルが生成するファイルの場所にあるときの直し方。"""
    if relative == GITATTRIBUTES_PATH:
        return (
            "手で書いた行を、パターンをリポジトリのルートからの相対に書き換えて (docs/.gitattributes のパターンは docs/ からの相対)、"
            "リポジトリのルートの .gitattributes に移してから、このファイルを消す"
        )
    return "ファイルの名前を変える。または、内容を手書きの文書に移してから、このファイルを消す"


def write_outputs(root: Path, outputs: dict[str, str]) -> tuple[list[str], list[str]]:
    """生成したファイルを書き、生成し直すと無くなるファイルを消す。書いたファイルと消したファイルを返す。

    消すのは、先頭の記述を持つファイル (生成したファイル) だけ。手書きのファイルは消さない。
    内容が同じファイルは書かない。生成するファイルの場所に手で書いたファイルがあれば、何も書かずに
    HandwrittenFilesError を送出する (呼び出し元が、そのパスの配列から利用者にエラーを伝える)。
    """
    # 生成するファイルの場所にある今のファイルを 1 回だけ読み、手で書いたファイルの判定と書く前の比較の両方に使う
    existing = {
        relative: generated_header.read_file(root / relative) for relative in outputs if (root / relative).is_file()
    }
    handwritten = [relative for relative, current in existing.items() if is_handwritten(current)]
    if handwritten:
        raise HandwrittenFilesError(handwritten)
    written: list[str] = []
    for relative, content in outputs.items():
        path = root / relative
        # 検査 a と同じ判定で比べる (改行の違いだけなら書かず、BOM や UTF-8 として読めないバイトがあれば上書きする)
        if relative in existing and existing[relative].matches(content):
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        written.append(relative)
    deleted: list[str] = []
    for relative in generated_files(root):
        if relative not in outputs:
            (root / relative).unlink()
            deleted.append(relative)
    return written, deleted

content.content:
"""検査 b (文書のリンクとアンカー)。

ドメインのディレクトリの下の手書きの Markdown について、次のことを検査する。形式の SSOT はプラグインの規則の文書
(ファイル doc-structured/rules/doc-structured-docs.md)。
  - 手書きのファイルの名前と場所 (モジュール documents が報告する)
  - 先頭のファイルの ID のアンカーと、その次の「#」の見出し
  - 節のアンカーの ID の形 (<ファイルの ID>-h-<名前>) と、その次の「##」から「######」の見出し。アンカーを付けた見出しにリンクが無い
  - 同じ ID のアンカーが 2 つ無い
  - リンクを reference-style ([ラベル]・[文][ラベル]) だけで書く ([文](URL)・<URL>・文中の URL・[ラベル][] が無い)
  - 定義の無いラベル・使われていない定義の行・同じラベルの定義の行が無い
  - 定義の行を末尾のまとまりに書き、段落の一部になっていない
  - 定義の行の href が、ID の形で、参照先のアンカーのあるファイルを指し、title が参照先の完全な名前と同じ
    (外部の URL の定義の行は、title を検査しない)
  - 初出: 各参照先を最初に指す箇所の表示の文が、参照先の書ける形 (完全な名前の先頭から親を 0 個以上省いた形) のどれかと同じ。
    参照先ごとに数え、外部の URL・参照先を求められないラベル・[ラベル][] は数えない
画像は規則の対象にしないので、本文のリンクで使われず、reference-style の画像だけが使うラベルの定義の行は、
href・title・使われていないことを検査しない。
"""

import posixpath
from dataclasses import dataclass

from . import markdown, names
from .documents import HandwrittenFile, Index, Target, section_name
from .names import IdError
from .problems import Problem

EXTERNAL_PREFIXES = ("http://", "https://")


def is_external(destination: str) -> bool:
    return strip_angle(destination).startswith(EXTERNAL_PREFIXES)


def strip_angle(destination: str) -> str:
    if destination.startswith("<") and destination.endswith(">"):
        return destination[1:-1]
    return destination


@dataclass(frozen=True)
class Resolved:
    """内部の定義の行の参照先。target が None なら、message が誤りの説明。

    by_id は、href の ID の参照先はあるがパスだけが違うときの、その参照先 (直し方が 1 つに決まる)。
    """

    target: Target | None
    message: str = ""
    by_id: Target | None = None


def resolve(handwritten: HandwrittenFile, definition: markdown.Definition, index: Index) -> Resolved:
    """内部の定義の行 (外部の URL でないもの) の href から、参照先を求める。"""
    destination = strip_angle(definition.destination)
    path, sep, fragment = destination.partition("#")
    if not sep or not fragment:
        return Resolved(None, f"href {destination} が ID のアンカー (#<ID>) を指していない")
    try:
        names.parse_id(fragment)
    except IdError as e:
        return Resolved(None, f"href の ID の形が違う: {e}")
    target = index.targets.get(fragment)
    if target is None:
        return Resolved(None, f"href の参照先 {fragment} のアンカーが無い")
    resolved = handwritten.path if not path else posixpath.normpath(posixpath.join(posixpath.dirname(handwritten.path), path))
    if resolved != target.path:
        return Resolved(
            None,
            f"href が、参照先 {fragment} のアンカーのあるファイルを指していない (正しい href は {target.href(handwritten.path)})",
            by_id=target,
        )
    return Resolved(target)


def definition_line(label: str, target: Target, from_path: str, quote: str = '"') -> str:
    """参照先 target を指す定義の行。"""
    title = markdown.escape_title(target.full_name(), quote)
    return f"[{label}]: {target.href(from_path)} {quote}{title}{markdown.closing_quote(quote)}"


def image_only_labels(document: markdown.Document) -> set[str]:
    """本文のリンクで使われず、reference-style の画像だけが使うラベル (比べる形)。"""
    used = {markdown.normalize_label(r.label) for r in document.references}
    return {markdown.normalize_label(label) for label in document.image_labels} - used


@dataclass(frozen=True)
class Use:
    """本文のリンクが、参照先を指す箇所。first は、そのファイルでその参照先を最初に指す箇所なら True。"""

    reference: markdown.Reference
    target: Target
    first: bool


def target_uses(handwritten: HandwrittenFile, document: markdown.Document, index: Index) -> list[Use]:
    """document (handwritten のファイルの内容) の本文のリンクのうち、参照先を求められるものを、行と列の順に並べる。

    [ラベル][] の形・外部の URL を指すラベル・定義の行の無いラベル・href から参照先を求められないラベルは含めない。
    同じラベルの定義の行が 2 つ以上あれば、最初の行で参照先を求める。
    """
    definitions: dict[str, markdown.Definition] = {}
    for definition in document.definitions:
        definitions.setdefault(markdown.normalize_label(definition.label), definition)
    uses: list[Use] = []
    seen: set[str] = set()
    for reference in document.references:
        if reference.form == "collapsed":
            continue
        definition = definitions.get(markdown.normalize_label(reference.label))
        if definition is None or is_external(definition.destination):
            continue
        target = resolve(handwritten, definition, index).target
        if target is None:
            continue
        uses.append(Use(reference, target, target.id not in seen))
        seen.add(target.id)
    return uses


def collapse_spaces(text: str) -> str:
    """連続する空白 (改行を含む) を空白 1 つにし、前後の空白を除いたもの。"""
    return " ".join(text.split())


def display_text(reference: markdown.Reference) -> str:
    """表示の文を、連続する空白 (改行を含む) を空白 1 つにし、前後の空白を除いた形にしたもの。"""
    return collapse_spaces(reference.text)


def is_writable(display: str, target: Target) -> bool:
    """表示の文 display (display_text の形) が、参照先の書ける形のどれかと同じか。書ける形の側も、連続する空白を
    空白 1 つにして比べる (見出しの文や日本語名に、全角空白や連続する空白があるため)。"""
    return display in {collapse_spaces(form) for form in target.writable_forms()}


def form_lines(forms: list[str]) -> str:
    """メッセージの後に続ける、書ける形の行。"""
    return "\n".join(f"  {form}" for form in forms)


def candidate_text(targets: list[Target]) -> str:
    return "、".join(f"{t.id} ({t.full_name()})" for t in targets)


class _FileChecker:
    def __init__(self, handwritten: HandwrittenFile, index: Index):
        self.file = handwritten
        self.document = handwritten.document
        self.index = index
        self.problems: list[Problem] = []

    def problem(self, message: str, line: int | None = None, column: int | None = None, detail: str = "") -> None:
        self.problems.append(Problem("b", self.file.path, message, line, column, detail))

    def check(self) -> list[Problem]:
        self.check_anchors()
        self.check_link_forms()
        self.check_definitions()
        self.check_first_uses()
        return self.problems

    def check_anchors(self) -> None:
        document = self.document
        file_id = self.file.id
        first = document.first_nonblank()
        file_anchor = next((a for a in document.anchors if a.line == first), None)
        if file_anchor is None:
            self.problem(f'先頭の行に、ファイルの ID のアンカー <a name="{file_id}"></a> が無い', first or 1, 1)
        elif file_anchor.name != file_id:
            self.problem(
                f"先頭のアンカーの ID {file_anchor.name} が、ファイルの ID {file_id} と違う",
                file_anchor.line, file_anchor.column,
            )
        if file_anchor is not None:
            following = document.next_nonblank(file_anchor.line)
            heading = document.heading_at(following) if following else None
            if heading is None or not heading.atx or heading.level != 1:
                self.problem("ファイルの ID のアンカーの次の行に、「#」の見出しが無い", file_anchor.line, file_anchor.column)
        for anchor in document.anchors:
            if anchor is file_anchor:
                continue
            if section_name(file_id, anchor.name) is None:
                self.problem(
                    f"節のアンカーの ID {anchor.name} は、{file_id}-{names.SECTION.symbol}-<名前> の形にする (名前は snake_case)",
                    anchor.line, anchor.column,
                )
                continue
            following = document.next_nonblank(anchor.line)
            heading = document.heading_at(following) if following else None
            if heading is None or not heading.atx or heading.level < 2:
                self.problem("節のアンカーの次の行に、「##」から「######」の見出しが無い", anchor.line, anchor.column)
                continue
            linked = [r for r in document.references if r.line == heading.line]
            linked += [r for r in document.inline_links if r.line == heading.line]
            if linked:
                self.problem(
                    "アンカーを付けた見出しにリンクを書かない (見出しの文は、参照する定義の行の title になるため)",
                    heading.line, linked[0].column,
                )
        for anchor in document.anchors:
            found = self.index.anchors.get(anchor.name, [])
            if len(found) > 1:
                others = [f"{path}:{a.line}" for path, a in found if not (path == self.file.path and a.line == anchor.line)]
                self.problem(f"同じ ID {anchor.name} のアンカーが {'、'.join(others)} にもある", anchor.line, anchor.column)

    def check_link_forms(self) -> None:
        for link in self.document.inline_links:
            self.problem(
                "[文](URL) の形でリンクを書かない。reference-style ([ラベル] か [文][ラベル]) と定義の行で書く",
                link.line, link.column,
            )
        for url in self.document.urls:
            if url.form == "autolink":
                message = f"<{url.url}> の形でリンクを書かない。reference-style ([ラベル] か [文][ラベル]) と定義の行で書く"
            else:
                message = (
                    f"文中に URL {url.url} をそのまま書かない。reference-style ([ラベル] か [文][ラベル]) と定義の行で書く"
                    "。リンクにしないときは、インラインコードにする"
                )
            self.problem(message, url.line, url.column)
        for reference in self.document.references:
            if reference.form == "collapsed":
                self.problem(
                    f"[{reference.text}][] の形で書かない。[{reference.text}] と書く", reference.line, reference.column
                )

    def check_definitions(self) -> None:
        document = self.document
        defined: dict[str, markdown.Definition] = {}
        images = image_only_labels(document)
        previous_in_paragraph = -1
        for definition in document.definitions:
            key = markdown.normalize_label(definition.label)
            where = (definition.line, definition.column)
            if definition.in_paragraph:
                if previous_in_paragraph != definition.line - 1:
                    self.problem("直前の行と同じ段落になり、定義の行として読まれない。前に空行を入れる", *where)
                previous_in_paragraph = definition.line
            elif definition.line <= document.body_end:
                self.problem("定義の行は、ファイルの末尾のまとまりに書く", *where)
            if key in defined:
                self.problem(f"ラベル {definition.label} の定義の行は、{defined[key].line} 行目にもある", *where)
                continue
            defined[key] = definition
            if key not in images:
                self.check_definition_target(definition)
        used: set[str] = set()
        for reference in document.references:
            key = markdown.normalize_label(reference.label)
            used.add(key)
            if reference.form == "collapsed" or key in defined:
                continue
            candidates = self.index.candidates(reference.label)
            if candidates:
                hint = f"。候補: {candidate_text(candidates)}"
            else:
                hint = "。参照先の候補は無い"
            self.problem(f"ラベル {reference.label} の定義の行が無い{hint}", reference.label_line, reference.label_column)
        for key, definition in defined.items():
            if key not in used and key not in images:
                self.problem(f"ラベル {definition.label} の定義の行が、本文で使われていない", definition.line, definition.column)

    def check_definition_target(self, definition: markdown.Definition) -> None:
        if is_external(definition.destination):
            return
        where = (definition.line, definition.column)
        resolved = resolve(self.file, definition, self.index)
        if resolved.target is None:
            self.problem(resolved.message, *where)
            return
        full_name = resolved.target.full_name()
        if definition.title is None:
            self.problem(f"定義の行に title が無い。参照先の完全な名前「{full_name}」を書く", *where)
        elif definition.title_text != full_name:
            self.problem(f"定義の行の title が、参照先の完全な名前「{full_name}」と違う", *where)

    def check_first_uses(self) -> None:
        for use in target_uses(self.file, self.document, self.index):
            if not use.first:
                continue
            display = display_text(use.reference)
            if is_writable(display, use.target):
                continue
            self.problem(
                f"参照先 {use.target.id} を最初に指す箇所の表示の文「{display}」が、書ける形のどれとも違う。書ける形:",
                use.reference.line, use.reference.column, form_lines(use.target.writable_forms()),
            )


def check_links(index: Index) -> list[Problem]:
    """検査 b: 手書きの Markdown のリンクとアンカー (手書きのファイルの名前と場所は、モジュール documents が報告する)。"""
    problems: list[Problem] = []
    for handwritten in index.files:
        problems += _FileChecker(handwritten, index).check()
    return problems
"""サブコマンド links-fix (手書きの Markdown の定義の行・ファイルのアンカー・リンクの表示の文を直す)。

直し方が 1 通りに決まるものだけを書き換え、判断の要るものは「パス:行:列: メッセージ」の形で報告する。
1 回の実行で、先に定義の行とファイルのアンカーを直し、その後にリンクの表示の文を直す。
  - 先頭の行 (空行を除く) がアンカーでなければ、ファイルの ID のアンカーを足す。先頭のアンカーの ID が違うときは、
    書き換えるか残すかの判断が要るので、足さずに報告する
  - 定義の無いラベルのうち、参照先の候補が 1 件のものに、定義の行を足す (本文で最初に使った順に、末尾のまとまりの後ろへ)
  - 定義の行の title が参照先の完全な名前と違えば、書き換える (引用符の種類は変えない。title が無ければ「"」で足す)
  - 使われていない定義の行を消す。ただし、同じファイルに定義の無いラベルが残るときは、消さずに報告する
    (ラベルの書き間違いのことがあるため)
  - 本文の途中の定義の行と、段落の一部になった定義の行を、末尾のまとまりに移す
  - 定義の行の href の ID が参照先にあり、パスだけが違えば、href を正しい値に書き換える
  - 同じラベルの定義の行のうち、参照先が同じものは後の行を消す。参照先が違えば報告する
reference-style の画像だけが使うラベルの定義の行は、画像が規則の対象でないので、消さず書き換えない (末尾のまとまりへは移す)。
リンクの表示の文 (参照先を求められるリンクだけ。数え方は検査 b の初出と同じ):
  - 各参照先を最初に指す箇所の表示の文が書ける形と違い、[ラベル] の形なら、[<書ける形>][ラベル] に書き換える。
    書ける形は、参照するファイルと共通の親を省き、略称のある種類は略称で書く
  - 2 回目以降の箇所の表示の文が参照先の ID か書ける形なら、名前が見える形 ([ラベル] か [名前][ラベル]) に書き換える。
    ドメインは名前を持たないので書き換えない。書いた人が選んだ文 (名前でも ID でも書ける形でもない文) は書き換えない
判断の要るもの: 参照先の候補が 0 件か複数のラベル・消さなかった使われていない定義の行・参照先の違う同じラベルの定義の行・
href から参照先を求められない、本文で使われている定義の行・ファイルの ID と違う先頭のアンカー・
最初の箇所の表示の文が書ける形と違う [文][ラベル] (文の意味が変わることがあるので、書き換えない)。
利用者が選んだ参照先は、Choice (オプション --choose) で受け取り、定義の行の href と title はツールが作る。
"""

from dataclasses import dataclass, field
from pathlib import Path

from . import markdown
from .documents import HandwrittenFile, Index
from .links import (
    candidate_text,
    definition_line,
    display_text,
    form_lines,
    image_only_labels,
    is_external,
    is_writable,
    resolve,
    strip_angle,
    target_uses,
