@dataclass(frozen=True)
class Choice:
    """利用者が選んだ参照先。value は参照先の ID か、外部の URL (http:// か https:// で始まるもの)。"""

    path: str  # リポジトリのルートからの相対パス
    label: str
    value: str


class ChoiceError(ValueError):
    """--choose の値が使えない。メッセージは利用者に見せる文。"""


@dataclass(frozen=True)
class Report:
    """判断の要るもの。"""

    path: str
    line: int
    column: int
    message: str
    detail: str = ""  # メッセージの後に続ける複数行 (書ける形の一覧)

    def format(self) -> str:
        text = f"{self.path}:{self.line}:{self.column}: {self.message}"
        if self.detail:
            text += "\n" + self.detail
        return text


@dataclass
class FixResult:
    changed: list[str] = field(default_factory=list)  # 書き換えたファイル
    reports: list[Report] = field(default_factory=list)

